'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('month','Old English monað, from Proto-Germanic *mēnōth-; the word is related to moon and originally followed a lunar cycle.',[C('month.s1','历法','The council meets on the first Monday of each month, so its annual calendar lists twelve regular meetings.','委员会每月第一个星期一开会，因此年度日历列出十二次例会。','The council meets on the first Monday of each month / so its annual calendar lists twelve regular meetings.','each month 指历法中的每一个月份。','一年分为十二个命名月份，句中安排重复的月度会议。'),C('month.s2','时长','The seedlings need about a month to establish roots, although cold weather may delay their growth.','幼苗大约需要一个月长稳根系，不过寒冷天气可能拖慢生长。','The seedlings need about a month / to establish roots / although cold weather may delay their growth.','a month 可作约三十天的时长，不必等同某个完整历月。','about 明示这里是大约一个月的时间。')],M('The calendar had twelve months, but the report called each named calendar division a month-long period of exactly thirty days.','The calendar had twelve named months, each with its own number of days.','calendar month 的天数不同，并非每个都正好三十天。','measurement'),[q('How many regular meetings appear on the annual calendar?','twelve','thirty','one hundred','每月一次，一年十二个月，因此共十二次。',1,'measurement'),q('How long do the seedlings need?','about thirty days','exactly twelve years','one afternoon','句中 about a month 表示大约三十天。',2,'measurement'),q('Which statement distinguishes the two senses?','A calendar month is named; a month as a duration is approximate.','Every month always lasts exactly thirty days.','A month can only mean a meeting.','月份是历法单位，时长用法通常是约三十天。',1,'distinction'),q('In each month, month is a?','count noun naming a calendar division','verb meaning to plant','measure of temperature','each 后的 month 是可数名词。',1,'grammar')]);
P('monthly','Monthly is formed from month plus -ly; it can describe something occurring every month or name a periodical issued each month.',[C('monthly.s1','周期频率','The tenants pay rent monthly by bank transfer, with each payment due on the first business day.','租户每月通过银行转账付租金，每笔款项在第一个工作日到期。','The tenants pay rent monthly / by bank transfer / with each payment due on the first business day.','monthly 作副词表示每月一次。','租金每月支付一次，符合频率义。'),C('monthly.s2','刊物','The museum’s monthly includes exhibition reviews, interviews, and a calendar of upcoming lectures.','博物馆的月刊刊登展览评论、访谈和即将举行的讲座日历。','The museum’s monthly includes exhibition reviews / interviews / and a calendar of upcoming lectures.','monthly 作名词可指月刊。','该刊物按月出版并包含编辑内容。')],M('The museum published its monthly every morning, although the title referred to a publication issued once a month.','The museum published its monthly once each month.','monthly 指每月一次的周期，不是每日。','meaning'),[q('How often is rent paid?','once each month','once each morning','once every decade','monthly 表示每月支付一次。',1,'meaning'),q('What does the museum’s monthly contain?','reviews, interviews, and a lecture calendar','only a rent invoice','a daily weather forecast','此处 monthly 是包含编辑内容的月刊。',2,'context'),q('Which phrase correctly describes a monthly publication?','a magazine issued once a month','a paper printed every hour','a book never reissued','月刊按月发行。',2,'word-choice'),q('In pay rent monthly, monthly functions as?','an adverb of frequency','a plural noun','a past-tense verb','monthly 修饰 pay，说明支付频率。',1,'grammar')]);
P('monument','Monument comes from Latin monumentum, “memorial,” from monere “to remind”; it can be a memorial structure, a protected historic building, or a lasting achievement.',[C('monument.s1','纪念建筑','The town raised a stone monument beside the station to honour the nurses who served during the flood.','镇上在车站旁立起石碑，纪念洪灾期间服务的护士。','The town raised a stone monument / beside the station / to honour the nurses who served during the flood.','monument 指为纪念人物或事件而建的建筑或雕像。','石碑用于纪念救灾护士。'),C('monument.s2','历史古迹','The medieval monastery is now a protected monument, and visitors must stay on the marked paths.','这座中世纪修道院如今是受保护的古迹，游客必须走标示路线。','The medieval monastery is now a protected monument / and visitors must stay on the marked paths.','受保护 monument 可指因历史价值而保存的旧建筑。','修道院因历史价值受到保护。'),C('monument.s3','不朽成果','Her carefully documented atlas became a monument to decades of field research.','她详尽记录的地图集成为数十年实地研究的不朽成果。','Her carefully documented atlas / became a monument to decades of field research.','a monument to 可比喻持久体现某种成就的作品。','地图集代表并保存了多年研究成果。')],M('The new memorial was called a monument, but it had been built solely as an ordinary bus shelter with no commemorative purpose.','The town built a monument to honour the flood-rescue workers.','作为普通候车亭且没有纪念目的的设施不符合纪念碑义。','meaning'),[q('Who is honoured by the stone monument?','the nurses who served during the flood','the station’s ticket clerks','the monastery visitors','碑文纪念洪灾期间服务的护士。',1,'context'),q('Why must visitors follow marked paths at the monastery?','it is a protected historic monument','it is a newly built shopping centre','it is an unoccupied bus shelter','monument 在此指受保护的历史建筑。',2),q('What does the atlas become figuratively?','a lasting record of decades of research','a stone statue beside a station','a monthly rent receipt','a monument to 可比喻持久体现某成就的作品。',3,'word-choice'),q('Which meaning of monument applies to a statue honouring a person?','a memorial structure','a temporary loan','a type of field research','纪念人物的雕像属于纪念建筑义。',1) ]);
P('monumental','Monumental is monument plus -al; from the sense of a monument it developed meanings for something exceptionally large or important and for memorial architecture.',[C('monumental.s1','规模或意义巨大','The engineers faced a monumental task: replacing the bridge without interrupting the only road into the valley.','工程师们面临一项艰巨工程：更换桥梁，同时不切断通往山谷的唯一道路。','The engineers faced a monumental task / replacing the bridge / without interrupting the only road into the valley.','monumental 修饰 task，强调规模或重要性非同一般。','更换唯一通道上的桥梁，工程规模和影响都很大。'),C('monumental.s2','纪念性建筑','The gallery’s monumental entrance was designed as a stone arch to commemorate the city’s founders.','美术馆的纪念性入口设计成石拱门，用来纪念城市的创建者。','The gallery’s monumental entrance / was designed as a stone arch / to commemorate the city’s founders.','monumental 可表示建筑具有纪念碑式的性质。','石拱门专为纪念城市创建者而建。')],M('The team described a routine five-minute form as a monumental undertaking, although it required no unusual effort or scale.','The team described rebuilding the valley’s only bridge as a monumental undertaking.','普通小任务没有非凡规模或重要性，不能恰当地称为 monumental。','word-choice'),[q('Why was replacing the bridge monumental?','it was a huge challenge affecting the valley’s only road','it took five minutes and changed nothing','it was a monthly meeting','monumental 指规模或重要性极大；唯一通路上的换桥工程符合。',1),q('What commemorative feature marks the gallery?','a stone-arch entrance','a temporary paper sign','a routine form','入口是纪念城市创建者的石拱门。',2),q('Which use is figurative rather than architectural?','a monumental task','a monumental stone entrance','a monumental memorial arch','task 用 monumental 表示极其艰巨。',1,'distinction'),q('Monumental is formed from monument plus?','-al','-less','-ment','monumental 由名词 monument 加形容词后缀 -al 构成。',1,'word-formation')]);
P('mood','Mood comes from Old English mod, “mind, spirit, courage”; modern uses include a person’s feeling, an atmosphere, and a grammatical verb form.',[C('mood.s1','个人情绪','After the long walk in the rain, his mood improved when he found a warm café and dry clothes.','雨中走了很久后，他找到温暖的咖啡馆和干衣服，心情才好起来。','After the long walk in the rain / his mood improved / when he found a warm café and dry clothes.','mood 指某人在特定时刻的情绪状态。','环境改善后，他的情绪也变好。'),C('mood.s2','作品气氛','Muted lighting and slow music created a reflective mood throughout the small exhibition.','柔和的灯光和舒缓的音乐为整个小型展览营造出沉思的气氛。','Muted lighting and slow music / created a reflective mood / throughout the small exhibition.','mood 也可指地点、作品或群体带给人的总体气氛。','灯光与音乐共同塑造展览氛围。'),C('mood.s3','语法语气','In “Close the door,” the imperative mood makes the verb express a command rather than a fact.','在“关上门”中，祈使语气使动词表达命令而非事实。','In “Close the door,” / the imperative mood / makes the verb express a command rather than a fact.','语法 mood 指动词形式所表达的陈述、命令或愿望等态度。','例句用祈使语气表达命令。')],M('The grammar guide called “Close the door” indicative mood because it reports a fact rather than giving an order.','The grammar guide called “Close the door” imperative mood because it gives an order.','祈使句发出命令，不是陈述事实。','grammar'),[q('What improved after the walk?','his emotional state','the exhibition’s lighting','the verb’s tense','句中 mood 指他的心情。',1),q('What created the exhibition’s reflective mood?','muted lighting and slow music','a grammar exercise','a warm café receipt','灯光与音乐共同营造氛围。',2),q('What does the imperative mood do in “Close the door”?','expresses a command','reports a past event','names a person’s feeling','祈使语气用来表达命令。',3,'grammar'),q('Which mood sense concerns the feeling a place gives visitors?','atmosphere','a person’s temporary emotion only','a verb form only','展览整体给人的感觉属于气氛义。',2,'distinction')]);
P('moody','Moody combines mood with -y; it describes someone whose feelings change readily or someone who is often quietly sad.',[C('moody.s1','情绪多变','The teenager seemed moody all week, cheerful at breakfast but irritated by small questions after school.','这个少年整周都显得喜怒无常，早餐时兴高采烈，放学后却会因小问题烦躁。','The teenager seemed moody all week / cheerful at breakfast / but irritated by small questions after school.','moody 可表示情绪无明显原因地快速变化。','同一人短时间内从愉快变烦躁，体现情绪多变。'),C('moody.s2','忧郁低沉','A moody portrait shows the musician sitting alone in a dim room, looking quiet and sad.','一幅忧郁的肖像画描绘音乐家独坐昏暗房间，神情安静而悲伤。','A moody portrait shows the musician sitting alone / in a dim room / looking quiet and sad.','用于人或艺术作品时，moody 也可强调忧郁、阴沉的感觉。','独坐昏暗房间、神情悲伤构成低沉氛围。')],M('The cheerful child whose feelings stayed steady all day was described as moody because she laughed once.','The child was described as moody because her feelings shifted quickly from cheerful to irritated.','偶尔发笑不等于情绪反复变化；语境要体现不稳定或忧郁。','word-choice'),[q('How did the teenager’s feelings vary?','from cheerful to irritated','from asleep to invisible','from hungry to taller','早餐愉快、放学后易怒，显示情绪变化。',1),q('What atmosphere does the portrait convey?','quiet sadness','loud celebration','scientific certainty','昏暗房间和悲伤神情营造忧郁感。',2),q('Which person is most clearly moody in the changing-feelings sense?','someone who shifts from cheerful to annoyed without much cause','someone who keeps a calm mood all day','someone who changes clothes twice','情绪无明显原因地迅速转变符合该义。',1,'context'),q('The suffix -y in moody forms?','an adjective from mood','a past tense from mood','a plural noun','moody 是 mood 加 -y 构成的形容词。',1,'word-formation')]);
P('moon','Moon continues Old English mona, from Proto-Germanic *mēnōn-; it names Earth’s satellite, a natural satellite of another planet, or (as a verb) idle daydreaming.',[C('moon.s1','地球卫星','A narrow crescent moon appeared above the harbour just after sunset, reflected in the still water.','日落后不久，一弯新月出现在港口上空，倒映在平静的水面。','A narrow crescent moon appeared above the harbour / just after sunset / reflected in the still water.','moon 常指地球唯一的天然卫星，也可按相位描述其可见形状。','新月形态出现在港口上空，指地球的月亮。'),C('moon.s2','其他行星卫星','The probe collected ice samples from a moon of Jupiter that orbits far beyond the planet’s bright cloud bands.','探测器从木星的一颗卫星采集冰样，这颗卫星绕行在明亮云带之外。','The probe collected ice samples / from a moon of Jupiter / that orbits far beyond the planet’s bright cloud bands.','moon 可泛指绕其他行星运行的天然卫星。','Jupiter 的天然卫星符合广义卫星义。'),C('moon.s3','出神闲荡','Instead of checking the map, the guide mooned beside the trail and let the group walk ahead.','导游没有查看地图，而是在小径旁发呆，让队伍走到了前面。','Instead of checking the map / the guide mooned beside the trail / and let the group walk ahead.','moon 作动词时可表示出神、闲荡而不做正事。','发呆而放任队伍前行，体现闲散走神。')],M('The astronomer called Europa Earth’s moon, although it orbits Jupiter rather than Earth.','The astronomer called Europa a moon of Jupiter.','moon 可指任一行星的天然卫星；Europa 绕木星运行，不是地球的月亮。','confusable'),[q('What shape did the harbour moon have?','a narrow crescent','a full square','a ring of ice on Jupiter','例句说明日落后可见一弯新月。',1),q('Which planet does the probe’s moon orbit?','Jupiter','Earth','Venus','第二例明确说卫星绕木星运行。',2),q('What did the guide do instead of checking the map?','daydreamed beside the trail','collected ice samples','repaired the harbour','moon 作动词可表示发呆闲荡。',3),q('Which statement is accurate?','Earth’s moon is one moon; Jupiter also has natural moons.','Only Earth can have a moon.','A moon is always a planet’s bright cloud band.','moon 可特指地球卫星，也泛指其他行星的卫星。',2,'distinction')]);
P('moor','The verb moor is probably related to an Old English word for a mooring rope or borrowed from a Germanic language; the noun moor comes from Old English mōr, “waste land.”',[C('moor.s1','系泊船只','Before the storm arrived, the crew moored the research boat to a heavy ring on the harbour wall.','风暴到来前，船员把研究船系泊在港墙上的重型铁环上。','Before the storm arrived / the crew moored the research boat / to a heavy ring on the harbour wall.','moor 作及物动词表示用绳索、链条或锚把船固定。','船被系在港墙铁环上以防风暴漂走。'),C('moor.s2','荒原','Heather covered the open moor, where sheep grazed among patches of wet ground and low shrubs.','石楠覆盖着开阔荒原，羊群在湿地和低矮灌木间吃草。','Heather covered the open moor / where sheep grazed / among patches of wet ground and low shrubs.','moor 作名词指土壤贫瘠、常有石楠的开阔荒地。','石楠、湿地与放牧景观呈现荒原地貌。')],M('The sailors left the boat drifting free, yet the log said they had moored it securely to the harbour wall.','The sailors moored the boat to the harbour wall with a line.','moor 表示固定船只；任其漂流与系泊相反。','meaning'),[q('What secured the research boat?','a heavy ring on the harbour wall','a field of heather','a mountain summit','船员将船系到港墙的铁环上。',1),q('What grows across the open moor?','heather and low shrubs','harbour ropes','tropical coral','句中石楠覆盖荒原，周围有湿地和灌木。',2),q('Which sentence uses moor as a verb?','They moored the boat before the storm.','They crossed the open moor on foot.','Heather covered the moor.','第一句里 moored 表示系住船只。',1,'grammar'),q('Which clue best identifies a moor as a landscape?','open poor-soil land with heather','a paved harbour wall','a motorized two-wheeled vehicle','石楠覆盖的贫瘠开阔地是荒原。',2,'context')]);
P('moorland','Moorland is a compound of moor and land, naming upland terrain made up of open moors, especially in Britain.',C('moorland.s1','高地地貌','The footpath crosses exposed moorland, where heather and coarse grass grow above the tree line.','这条步道穿过无遮蔽的高地荒原，石楠和粗草生长在林木线以上。','The footpath crosses exposed moorland / where heather and coarse grass grow / above the tree line.','moorland 是由一片片荒原构成的高地地带。','植被低矮且位于林木线之上，符合荒原地貌。'),M('The guide described the dense tropical rainforest beside the equator as moorland.','The guide described the open, heather-covered upland as moorland.','热带密林与开阔高地荒原的地貌相反。'),[q('What grows on the exposed moorland?','heather and coarse grass','tall tropical palms','harbour ropes','荒原上生长石楠和粗草。'),q('Where does the footpath run?','above the tree line','under the ocean','inside a city station','句中路线经过林木线以上的高地。',1),q('Which place is most likely moorland?','open upland covered with heather','a dense equatorial rainforest','a paved urban square','开阔高地和石楠是 moorland 的典型线索。',1,'context'),q('Moorland is a compound of moor and?','land','line','light','moorland 由 moor 与 land 组成。',1,'word-formation')]);
P('moose','Moose entered English in the early seventeenth century from an Algonquian language, probably Narragansett moos or Abenaki moz; its plural is also moose.',C('moose.s1','动物与复数','A moose crossed the logging road at dusk, and two more appeared near the marsh before the ranger arrived.','黄昏时一头驼鹿穿过伐木路；护林员到达前，沼泽旁又出现两头。','A moose crossed the logging road at dusk / and two more appeared near the marsh / before the ranger arrived.','moose 指大型鹿科动物；复数仍写 moose，不加 -s。','一头与两头的写法均为 moose。'),M('Three mooses stood beside the marsh, where the ranger watched them from the road.','Three moose stood beside the marsh, where the ranger watched them from the road.','moose 的通常复数形式与单数同形。','plural'),[q('How many moose appeared in total?','three','one','five','一头过路，另有两头出现，合计三头。',1,'measurement'),q('What is the usual plural of moose?','moose','mooses','moosees','该词单复数同形。',1,'plural'),q('Where did the animals appear?','near the marsh','inside the ranger station','on the harbour wall','例句说另两头在沼泽附近出现。',1,'context'),q('From which language family did English borrow moose?','an Algonquian language','Latin','Old Norse','英语 moose 借自阿尔冈昆语族语言。',1,'word-formation')]);
P('mop','Mop is recorded in early modern English with uncertain ultimate origin; it names a floor-cleaning tool, a thick mass of hair, and the act of wiping with one.',[C('mop.s1','清洁工具','She wrung out the mop after washing the kitchen floor and left it upright in the ventilated cupboard.','她拖完厨房地板后拧干拖把，把它竖放在通风柜里。','She wrung out the mop / after washing the kitchen floor / and left it upright in the ventilated cupboard.','mop 作名词指带软头、用于擦洗地面的长柄工具。','拧干并竖放的清洁用品是拖把。'),C('mop.s2','蓬乱头发','A mop of dark curls fell over the child’s eyes, so the barber trimmed the fringe before the school photograph.','一团蓬乱的黑卷发垂到孩子眼前，因此理发师在学校拍照前修剪了刘海。','A mop of dark curls fell over the child’s eyes / so the barber trimmed the fringe / before the school photograph.','a mop of hair 是口语说法，指浓密蓬乱的一团头发。','卷发垂到眼前，呈现蓬乱发团。'),C('mop.s3','擦拭液体','The server mopped up the spilled tea before a customer slipped on the wet tiles.','服务员在顾客踩到湿瓷砖滑倒前，把洒出的茶水擦掉。','The server mopped up the spilled tea / before a customer slipped / on the wet tiles.','mop up 表示用拖把或布擦去液体。','擦掉地面茶水以消除滑倒危险。')],M('The server mopped up the tea by leaving the puddle untouched on the tiles.','The server mopped up the tea with a cloth before anyone slipped.','液体被留在地面上就没有擦掉，和 mop up 的动作相反。','meaning'),[q('Where did she leave the cleaning tool?','upright in a ventilated cupboard','on the child’s head','inside the tea cup','她把拖把竖放在通风柜里。',1),q('What fell over the child’s eyes?','a thick mass of dark curls','a floor-cleaning handle','a tea stain','a mop of curls 指一团浓密卷发。',2),q('What did the server mop up?','spilled tea','the customer’s hair','the school photograph','mop up 表示擦掉洒出的茶水。',3,'context'),q('Which expression commonly means remove a spill?','mop up the liquid','mop over the customer','mop into the cupboard','mop up + 液体表示将其擦净。',3,'collocation')]);
P('moped','Moped was formed in Swedish from parts of motor and pedal, then entered English for a light motorized bicycle.',C('moped.s1','轻型车辆','He rode a moped to the farm because the narrow lane was too rough for the delivery van.','他骑轻便摩托车去农场，因为狭窄小路崎岖，货车难以通行。','He rode a moped to the farm / because the narrow lane / was too rough for the delivery van.','moped 指轻型两轮机动车，词源融合 motor 与 pedal。','车辆可在狭窄乡间路行驶，符合轻便摩托车义。'),M('The delivery driver loaded the moped onto a trailer and described the large van itself as the small two-wheeled vehicle.','The delivery driver rode the small two-wheeled moped along the narrow lane.','moped 是轻型两轮车，不是大型货车。'),[q('Why did he use the moped?','the lane was too rough for the van','the road was an ocean channel','the farm had no entrance','崎岖窄路不适合货车，因此他骑轻型车。',1),q('A moped is generally?','a light motorized two-wheeler','a large delivery van','a four-wheeled tractor','moped 是轻型两轮机动车。',1,'context'),q('Which two ideas are reflected in the word’s Swedish formation?','motor and pedal','moon and road','moss and stone','moped 由 motor 与 pedal 的片段组成。',1,'word-formation'),q('What vehicle did he ride to the farm?','a moped','a railway carriage','a sailing boat','原句明确说他骑 moped 去农场。',1) ]);
P('moraine','Moraine came through French from Savoy dialect morena, “mound of earth”; its deeper source is uncertain and possibly pre-Latin Alpine.',C('moraine.s1','冰川沉积','The geologist mapped a crescent-shaped moraine of gravel and boulders left at the glacier’s former edge.','地质学家绘出一道弧形冰碛，由砾石和巨石构成，留在冰川昔日边缘。','The geologist mapped a crescent-shaped moraine / of gravel and boulders / left at the glacier’s former edge.','moraine 指冰川边缘或底部沉积的岩屑、砂土和砾石。','沉积物沿冰川昔日边缘形成弧形脊。','context'),M('The geologist labelled a ridge of gravel deposited by a glacier a coral reef formed in warm seawater.','The geologist labelled the glacier-deposited ridge a moraine.','冰川沉积的岩屑脊是冰碛，不是海洋珊瑚礁。','meaning'),[q('What material formed the mapped moraine?','gravel and boulders','fresh coral and shells','wooden railway sleepers','例句列出砾石与巨石。',1,'context'),q('Where was the moraine left?','at the glacier’s former edge','in a tropical lagoon','inside the glacier research tent','冰碛堆积在冰川昔日边缘。',1),q('Which process most directly creates a moraine?','a glacier deposits debris','a river evaporates','a volcano melts a bridge','冰川搬运并沉积岩屑形成冰碛。',1,'word-choice'),q('What is known about moraine’s deeper origin?','it is uncertain and may come from an Alpine source','it is certainly a Latin word meaning coral','it was coined from motor and pedal','该词经法语而来，更早词源尚不确定。',1,'word-formation')]);
P('moral','Moral comes from Latin moralis, “pertaining to character or manners”; it can concern right and wrong, ethical support, a story’s lesson, or standards of conduct.',[C('moral.s1','伦理判断','The committee made a moral decision to disclose the safety risk even though the announcement could delay the project.','委员会作出道德上的决定，公开安全风险，尽管公告可能拖延项目。','The committee made a moral decision / to disclose the safety risk / even though the announcement could delay the project.','moral 作形容词指涉及是非对错或伦理原则。','为维护公众知情而公开风险，属于伦理判断。'),C('moral.s2','精神支持','The injured runner received moral support from teammates who stayed beside her during rehabilitation.','受伤的跑者在康复期间得到队友的精神支持，他们一直陪在她身边。','The injured runner received moral support / from teammates / who stayed beside her during rehabilitation.','moral support 是原则或情感上的支持，不一定提供实际帮助。','陪伴鼓励属于精神支持。'),C('moral.s3','故事寓意','The fable’s moral is that a small act of honesty can prevent a much larger conflict.','这则寓言的寓意是，小小的诚实之举可以避免更大的冲突。','The fable’s moral / is that a small act of honesty / can prevent a much larger conflict.','moral 作名词指故事传达的行为教训。','句子概括寓言所教的道理。'),C('moral.s4','道德规范','The survey asked whether changing social morals had altered expectations about privacy.','调查询问社会道德规范的变化是否改变了人们对隐私的期待。','The survey asked whether changing social morals / had altered expectations / about privacy.','morals 常用复数表示社会或个人的行为准则。','调查讨论的是社会行为规范。')],M('The fable’s moral was the stone monument beside the station, rather than the lesson its characters learned.','The fable’s moral was that honesty can prevent conflict.','故事 moral 作名词指教训，不是故事里的一件物体。'),[q('Why did the committee disclose the risk?','to follow an ethical duty','to provide a teammate with a loan','to state a fable’s ending','moral decision 涉及伦理责任。',1),q('What kind of support did teammates provide?','encouragement during rehabilitation','a legal claim on the runner’s house','a grammatical verb form','moral support 是精神上的鼓励。',2),q('What is the fable’s moral?','honesty can prevent conflict','the committee delayed a project','privacy always means a building','寓意总结故事传达的教训。',3),q('In social morals, morals refers to?','standards of good behaviour','the number of calendar months','a memorial building','复数 morals 指行为准则。',4,'distinction')]);
P('morale','Morale came into English from French morale, related to moral; it names the confidence and enthusiasm felt by a group.',C('morale.s1','团队士气','After the repair team finished the dangerous night shift safely, the supervisor praised their work to restore morale.','维修队安全完成危险的夜班后，主管表扬了他们的工作，以提振士气。','After the repair team finished the dangerous night shift safely / the supervisor praised their work / to restore morale.','morale 指一个群体的信心与热情，常用于团队、部队或组织。','表扬团队表现是为了恢复集体信心。'),M('The supervisor said morale had improved, but every worker had lost confidence and refused to continue.','The supervisor said morale had improved because workers regained confidence and energy.','失去信心、拒绝继续工作与士气提升相矛盾。','meaning'),[q('What helped restore the team’s morale?','the supervisor praised their safe work','the team’s pay date moved to next month','a grammar lesson was cancelled','主管表扬安全完成工作来鼓舞团队。'),q('Morale is mainly about a group’s?','confidence and enthusiasm','monthly calendar','private mortgage','morale 指群体信心与热情。'),q('Which situation shows high morale?','a team feels confident and eager after a success','a team has given up and expects failure','a building is protected for its history','信心与积极性高说明士气好。',1,'context'),q('Morale differs from moral because morale refers to?','group confidence and spirit','a lesson in a fable only','a rule about right and wrong','morale 指士气，moral 常指伦理或寓意。',1,'confusable')]);
P('moralism','Moralism is formed from moral plus -ism and refers to stressing moral rules, sometimes without enough attention to circumstances or understanding.',C('moralism.s1','道德说教','The novel critic criticised the film’s moralism because every character was judged by a rigid rule, with little attention to their circumstances.','小说评论家批评电影的道德说教，因为影片用僵硬规则评判每个角色，却很少考虑他们的处境。','The novel critic criticised the film’s moralism / because every character was judged by a rigid rule / with little attention to their circumstances.','moralism 常指强调道德规条的态度，有时带有不顾情境的批评意味。','评论批评影片只套用规则、忽略人物处境。'),M('The reviewer praised the film’s moralism for carefully considering each character’s circumstances and avoiding rigid moral judgement.','The reviewer criticised the film’s moralism for applying rigid rules without considering circumstances.','不顾情境而僵硬说教才是 moralism 常受批评的特点。','word-choice'),[q('Why did the critic object to the film’s moralism?','it judged everyone by rigid rules without considering context','it refused to include any moral question','it showed a map of a mountain','评论指出其僵硬判定忽略人物处境。'),q('Moralism puts strong emphasis on?','moral rules','monthly publication dates','weather measurement','moralism 与道德规条的强调有关。'),q('Which review best identifies moralism?','The story lectures readers with fixed rules and little nuance.','The story explores motives without judging them.','The story lists the actors’ names.','僵硬说教、缺少情境考量符合 moralism。',1,'context'),q('The ending -ism here forms?','a noun naming an approach or doctrine','a comparative adjective','a past-tense verb','moralism 是表示思想或态度的名词。',1,'word-formation')]);
P('moralistic','Moralistic is moral plus -istic and describes a person or work that readily judges behaviour by strict moral rules.',C('moralistic.s1','说教评判','The reviewer found the lecture moralistic: it condemned every character’s choices without asking what pressures they faced.','评论者认为这场讲座说教味很重：它谴责每个角色的选择，却不问他们承受了什么压力。','The reviewer found the lecture moralistic / it condemned every character’s choices / without asking what pressures they faced.','moralistic 常带批评意味，指轻率地用严格标准训诫他人。','讲座不看人物处境，只作道德谴责。'),M('The essay was called moralistic because it neutrally examined competing pressures and avoided judging anyone.','The essay was called moralistic because it condemned every choice by a rigid standard.','中立考察多方处境并避免评判，不符合“好说教”的批评义。','word-choice'),[q('What made the lecture moralistic?','it condemned choices without considering pressures','it compared two mountain ranges','it praised every character’s actions','不考虑处境而谴责选择体现说教式评判。'),q('Which description fits a moralistic speaker?','one who quickly lectures others by strict rules','one who reports facts without judgement','one who issues a monthly magazine','moralistic 指容易用严苛道德标准训诫别人。'),q('Why is moralistic often a criticism?','it can suggest rigid judgement and preaching','it always means silent approval','it refers only to a person’s mood','该词常批评僵硬评判和说教。',1,'register'),q('Which ending appears in moralistic?','-istic','-less','-ship','moralistic 以形容词后缀 -istic 构成。',1,'word-formation')]);
P('morality','Morality comes through French moralité from Latin moralitas, formed from moralis; it refers to principles distinguishing right from wrong.',C('morality.s1','道德原则','The debate examined whether morality requires people to tell the truth even when honesty carries a personal cost.','辩论探讨道德是否要求人们即使诚实会让自己付出代价，也要说真话。','The debate examined whether morality requires people to tell the truth / even when honesty carries a personal cost.','morality 指判断行为对错的道德原则体系。','问题讨论诚实义务及其伦理依据。'),M('The ethics course defined morality as the colour pattern of an animal’s fur rather than principles of right and wrong.','The ethics course defined morality as principles used to judge right and wrong.','动物毛色花纹与道德原则无关。','meaning'),[q('What issue did the debate examine?','whether truth-telling is a moral duty','how a glacier deposits gravel','how often rent is paid','讨论的是诚实是否属于道德义务。'),q('Morality concerns principles of?','right and wrong','vehicle speed only','monthly publishing','morality 涉及行为的对错原则。'),q('Which question is about morality?','Is it right to keep a promise when it becomes costly?','How many moons orbit Jupiter?','Where should a mop be stored?','是否应守承诺属于道德判断。',1,'context'),q('Morality is an abstract noun related to?','moral','moose','moraine','morality 源自 moral 相关词形。',1,'word-formation')]);
P('moralize','Moralize entered English through French moraliser from medieval Latin moralizare; it means to lecture someone about right and wrong, often preachily.',C('moralize.s1','说教训诫','Rather than moralize about the delay, the coach asked what obstacle had prevented the players from arriving on time.','教练没有就迟到问题说教，而是询问是什么障碍让队员没能准时到达。','Rather than moralize about the delay / the coach asked what obstacle / had prevented the players from arriving on time.','moralize 作动词指以说教口吻谈论对错。','教练选择了解实际原因而非进行道德训诫。'),M('The coach moralized by asking calmly for the practical cause and offering help without judging anyone.','The coach moralized about punctuality, lecturing the players before asking what had happened.','中立询问原因并提供帮助不是说教；说教包含道德训诫。','word-choice'),[q('What did the coach do instead of moralizing?','asked about the obstacle causing the delay','punished every player without asking','described a protected monument','教练先询问导致迟到的障碍。'),q('To moralize is to talk in a?','preachy way about right and wrong','scientific way about glaciers','monthly way about rent','moralize 指说教式地谈道德对错。'),q('Which action is moralizing?','lecturing someone that lateness shows bad character','checking whether a train is late','asking neutrally about a road closure','用道德口吻训斥迟到者属于 moralize。',1,'context'),q('Moralize is used as a?','verb','plural noun only','comparative adjective','moralize 表示“说教、训诫”，是动词。',1,'grammar')]);
P('morally','Morally is moral plus -ly; it means from an ethical point of view or in a way that follows moral principles.',C('morally.s1','伦理判断副词','The lawyer argued that the company was legally permitted to close the clinic but morally obliged to give patients advance notice.','律师认为公司虽依法可以关闭诊所，但在道义上有责任提前通知患者。','The lawyer argued / that the company was legally permitted to close the clinic / but morally obliged to give patients advance notice.','morally 修饰 obliged，表示从伦理角度负有义务。','法律许可与道德责任在句中形成区分。'),M('The lawyer said the company was morally obliged to give notice, meaning it had a legal duty imposed by statute.','The lawyer said the company was ethically obliged to give notice, though that duty was not necessarily a legal requirement.','morally 表示道义上，不等同于法律强制义务。','distinction'),[q('What did the lawyer say the company should do ethically?','give patients advance notice','close the clinic without warning','publish a monthly magazine','律师说公司有道义责任提前通知患者。'),q('Morally in the sentence means?','from an ethical point of view','according to the weather','once each month','morally 表示从伦理角度看。'),q('Which statement keeps the legal and moral ideas distinct?','An act may be legal but still ethically questionable.','Anything legal is automatically morally required.','A moral duty is always a court order.','法律许可不必然等同于道德上正确或有义务。',1,'distinction'),q('Morally modifies which idea in morally obliged?','the obligation','the clinic building','the month','副词 morally 修饰形容词 obliged。',1,'grammar')]);
P('moratorium','Moratorium comes from Late Latin moratorius, “delaying,” related to morari “to delay”; it is an officially agreed temporary suspension.',C('moratorium.s1','暂缓令','The city imposed a six-month moratorium on new riverfront construction while engineers assessed flood risks.','工程师评估洪灾风险期间，市政府暂停批准新的河滨建设项目，为期六个月。','The city imposed a six-month moratorium / on new riverfront construction / while engineers assessed flood risks.','moratorium 指由权力机构或协议授权的临时暂停。','建造活动暂时中止，并明确了评估期间。'),M('The council announced a moratorium on building, then issued permits for every new riverfront project the same day.','The council paused new riverfront permits for six months while the flood study continued.','若仍立即批准新项目，就没有真正暂停相关活动。','meaning'),[q('What activity did the city suspend?','new riverfront construction','all river flow','monthly rent payments','市府暂停新的河滨建设。'),q('How long was the moratorium?','six months','six days','one decade','公告明确规定六个月。',1,'measurement'),q('Which event best fits a moratorium?','a temporary official pause on new permits','a permanent opening of every construction site','a routine monthly inspection','moratorium 是官方或协议批准的暂时中止。',1,'context'),q('Why did the city impose it?','to assess flood risks before allowing more building','to celebrate a completed bridge','to rename the river','暂停期间工程师评估洪灾风险。',1,'context')]);
P('morbid','Morbid comes from Latin morbidus, “diseased,” from morbus “illness”; it describes an unhealthy fascination with death or a condition caused by disease.',[C('morbid.s1','病态兴趣','The documentary avoided morbid detail and focused instead on how investigators identified the missing hikers.','纪录片避开病态而猎奇的细节，转而讲述调查人员如何确认失踪徒步者的身份。','The documentary avoided morbid detail / and focused instead / on how investigators identified the missing hikers.','morbid 可形容对死亡或痛苦有不健康的兴趣。','叙述刻意避开猎奇细节，体现该词的语域。'),C('morbid.s2','医学病理','The scan showed no morbid change in the tissue, so the specialist recommended routine follow-up rather than urgent treatment.','扫描未显示组织有病理性变化，因此专家建议常规复查而非紧急治疗。','The scan showed no morbid change in the tissue / so the specialist recommended routine follow-up / rather than urgent treatment.','医学语境中 morbid 指由疾病引起或与病态变化有关。','组织是否有病变决定是否急诊处理。')],M('The presenter was called morbid for discussing death in a careful medical report without expressing any unhealthy fascination.','The presenter was called morbid for dwelling eagerly on graphic details of death for shock value.','客观医学讨论不等于病态迷恋；此处要有不健康的猎奇兴趣。','word-choice'),[q('What did the documentary avoid?','unhealthy, graphic fascination with death','routine follow-up scans','a list of river permits','它避免猎奇的死亡细节。',1),q('What did the scan show?','no disease-related tissue change','a new riverfront building','a grammatical command','医学义的 morbid 涉及病理变化。',2,'context'),q('Which use of morbid is medical?','morbid change in tissue','a morbid fascination with violent stories','a morbid sense of humour','组织因疾病产生的变化属于医学用法。',2,'distinction'),q('Which person is best described as morbid in the unhealthy-interest sense?','someone who seeks graphic death stories for excitement','a doctor neutrally explaining a diagnosis','a patient scheduling a follow-up','病态义要求不健康地迷恋死亡或痛苦。',1,'context')]);
P('more','More continues Old English māra, the comparative of much and many; it can mean a greater amount, a greater degree, or something additional.',[C('more.s1','数量增加','The pantry needs more rice before the volunteers can prepare dinner for the extra guests.','志愿者要为新增客人准备晚饭，储藏室还需要更多米。','The pantry needs more rice / before the volunteers can prepare dinner / for the extra guests.','more 作限定词或代词表示较大的数量或额外数量。','新增客人使所需米量增加。'),C('more.s2','程度比较','The northern route is more difficult in winter because ice covers its steepest section.','北线冬季更加难走，因为最陡的一段会结冰。','The northern route is more difficult in winter / because ice covers its steepest section.','more 可置于形容词前构成比较级，表示程度更高。','与其他季节或路线相比，难度增加。'),C('more.s3','另外补充','The report lists the bridge repairs; more, it explains how the detour affects village buses.','报告列出桥梁维修情况；此外，还说明绕行会如何影响村里的公交车。','The report lists the bridge repairs / more, it explains how the detour affects village buses.','句首 more 可较正式地表示“此外、再者”。','第二部分补充了另一条相关信息。')],M('The cooks had less rice after receiving a larger delivery, so they asked the pantry for more.','The cooks had more rice after the larger delivery.','more 表示数量增加；更大的送货量不会使米变少。','meaning'),[q('Why does the pantry need more rice?','extra guests are coming to dinner','the northern route has ice','the report has a detour map','新增客人增加了晚餐所需食物。',1),q('Why is the northern route more difficult?','ice covers its steepest section','it has fewer guests','the report is shorter','结冰让北线冬季更难走。',2),q('What does the report add after listing repairs?','how the detour affects buses','a second list of rice varieties','the exact mood of the volunteers','more 引出补充信息。',3),q('In more difficult, more signals?','a greater degree','an additional person only','a point in the past','more 修饰形容词 difficult，表示程度更高。',2,'grammar')]);
P('more badly','More badly is the regular analytic comparative of the adverb badly, used to compare how poorly actions are performed.',C('more badly.s1','副词比较级','The second draft was more badly organised than the first: its evidence appeared after the conclusion instead of before it.','第二稿的组织比第一稿更糟：证据出现在结论之后，而不是之前。','The second draft was more badly organised than the first / its evidence appeared after the conclusion / instead of before it.','more badly 修饰过去分词 organised，比较两稿组织得有多差。','证据位置倒置说明第二稿组织更差。'),M('The second draft was more badly organised even though every section followed a clearer order and the evidence came first.','The second draft was more badly organised because its evidence came after the conclusion.','组织更清晰、证据顺序正确不能支持“更糟”的判断。','word-formation'),[q('What was worse in the second draft?','the organisation of its evidence','the number of calendar months','the spelling of moped','第二稿的证据顺序更差。',1),q('More badly is a comparative form of?','badly','bad','badness','more badly 比较动作或状态的糟糕程度。',1,'word-formation'),q('Which sentence uses more badly naturally?','The report was more badly organised than the earlier version.','She sings more badly than yesterday is the best singer.','The route is more badly than the bridge.','more badly 修饰 organised，构成副词比较表达。',1,'grammar'),q('What evidence supports the comparison?','the evidence comes after the conclusion','the second draft is shorter','the first draft has a title','证据位置在结论之后，体现更差的组织。',1,'context')]);
P('more distant','More distant is the analytic comparative of distant; it can describe greater physical separation or a less close relationship.',[C('more distant.s1','空间距离','The newer observatory lies more distant from the city lights than the old one, giving astronomers a darker sky.','新天文台比旧址离城市灯光更远，能为天文学家提供更暗的天空。','The newer observatory lies more distant from the city lights / than the old one / giving astronomers a darker sky.','more distant 可比较两个地点之间更大的空间距离。','远离城市灯光改善了夜空观测条件。'),C('more distant.s1','关系疏远','After the disagreement, the cousins became more distant and stopped sharing plans for family gatherings.','争执后，表亲之间变得更加疏远，也不再分享家庭聚会的安排。','After the disagreement / the cousins became more distant / and stopped sharing plans for family gatherings.','more distant 也可指人与人之间的关系较不亲近。','停止分享家庭安排显示关系疏远。')],M('The observatory was more distant from the city when it was built beside downtown than the remote site in the hills.','The observatory in the hills was more distant from city lights than the downtown site.','市中心地点比山中远郊更靠近城市灯光，距离比较方向颠倒。','distinction'),[q('Why is the newer observatory useful?','it is farther from city lights','it is inside the city centre','it has more family gatherings','远离灯光使夜空更暗。',1),q('How did the cousins’ relationship change?','they became less close','they moved farther from a city','they began sharing more plans','争执后他们不再分享安排，关系疏远。'),q('Which use is figurative?','The cousins grew more distant after the argument.','The observatory is more distant from downtown.','The moon is distant from Earth.','亲属关系的疏远是比喻用法。',1,'distinction'),q('More distant compares?','distance or closeness between two things','the weight of a monthly issue','the number of moose','该比较级可以谈空间远近或关系亲疏。',1,'meaning')]);
P('more precisely','More precisely is a comparative adverbial phrase used to replace or refine an earlier statement with a more exact one.',C('more precisely.s1',' уточ化表述','The sample was collected in northern Wales—more precisely, on the coast near Aberystwyth—during the spring survey.','样本采集于威尔士北部；更准确地说，是在阿伯里斯特威斯附近的海岸，于春季调查期间取得。','The sample was collected in northern Wales / more precisely, on the coast near Aberystwyth / during the spring survey.','more precisely 引出对前述地点的更精确说明。','较宽泛的“威尔士北部”被缩小到具体海岸位置。'),M('The report said “northern Wales—more precisely, somewhere in Europe,” replacing a specific location with a broader one.','The report refined “northern Wales” to the coast near Aberystwyth.','more precisely 应把信息说得更具体，而非改成更宽泛的地点。','word-choice'),[q('Where exactly was the sample collected?','on the coast near Aberystwyth','somewhere in Europe','in the city of London','后文用 more precisely 指明靠近阿伯里斯特威斯的海岸。'),q('What does more precisely do in the sentence?','refines a broad location with a narrower one','introduces an unrelated conclusion','shows the sample was collected monthly','该短语引出更精确的地点信息。'),q('Which continuation uses more precisely correctly?','The lab is in the north—more precisely, in Leeds.','The lab is in Leeds—more precisely, somewhere in the country.','The lab is open—more precisely, it has a door.','后续信息应缩小或细化前述范围。',1,'context'),q('More precisely most nearly means?','to state the point with greater exactness','to state it less carefully','to repeat it every month','该表达表示更准确地说。',1,'meaning')]);
P('more than','More than combines more with than to express an amount exceeding a stated number or quantity.',C('more than.s1','数量超过','More than forty families registered for the shelter, so the organisers opened a second room for overnight stays.','登记入住避难所的家庭超过四十户，因此组织者又开放了一间过夜房。','More than forty families registered for the shelter / so the organisers opened a second room / for overnight stays.','more than + 数量表示超过该数值，不包含“恰好只有该数”。','人数超过容量预估，因而需要增开房间。'),M('Exactly forty families registered, but the notice said more than forty had signed up.','More than forty families registered, so the total was above forty.','恰好四十不超过四十；more than 表示大于。','measurement'),[q('How many families registered?','over forty','exactly four','fewer than ten','more than forty 表示超过四十户。',1,'measurement'),q('Why did organisers open another room?','registration exceeded the expected capacity','only one family arrived','the shelter was on a mountain','登记人数超过预期，需要增加空间。',1,'context'),q('If more than 40 applies, which total qualifies?','41','40 exactly','39','超过四十的最小整数是四十一。',1,'measurement'),q('Which phrase means a quantity greater than the stated number?','more than','less than','the same as','more than 表示数量超过后接数字或名词。',1,'distinction')]);
P('moreover','Moreover combines more and over and functions as a formal linking adverb that adds a further supporting point.',C('moreover.s1','补充论据','The route is shorter; moreover, it avoids the bridge that is closed for repairs this week.','这条路线更短；此外，它还避开了本周因维修而封闭的桥梁。','The route is shorter / moreover, it avoids the bridge / that is closed for repairs this week.','moreover 常用于句首或分句间，补充支持前述观点的信息。','避开封桥是支持选这条路线的额外理由。'),M('The route was shorter; moreover, it was actually three kilometres longer than the alternative.','The route was shorter; moreover, it avoided the closed bridge.','后半句若与“更短”矛盾，就不是进一步支持该观点的理由。','context'),[q('What additional advantage does the route have?','it avoids a bridge closed for repairs','it crosses the closed bridge','it adds three kilometres','moreover 后补充了避开封桥这一优点。'),q('Moreover functions mainly as a?','linking adverb adding another point','noun for a vehicle','verb meaning to repair','moreover 用来连接并补充论点。',1,'grammar'),q('Which sentence uses moreover coherently?','The plan saves fuel; moreover, it reduces travel time.','The plan saves fuel; moreover, it uses twice as much fuel.','Moreover the wrench under the table.','第二个优点应支持或补充前一主张。',1,'context'),q('Why choose the route this week?','it is shorter and avoids the repair closure','it is longer and crosses a closed bridge','it has more difficult grammar','路线更短且避开封闭桥梁。',1) ]);
P('morgue','Morgue came from French morgue, first for a place where unidentified bodies could be viewed and later for a room or building that stores corpses.',C('morgue.s1','遗体存放场所','The hospital transferred the unidentified body to the morgue while investigators contacted relatives and reviewed missing-person reports.','医院把身份不明的遗体移至太平间，同时调查人员联系亲属并查阅失踪人员报告。','The hospital transferred the unidentified body to the morgue / while investigators contacted relatives / and reviewed missing-person reports.','morgue 指暂时存放遗体的房间或建筑。','等待身份确认期间，遗体被转至专门场所。'),M('The hospital sent the unidentified body to the morgue for overnight accommodation as if it were a guest room.','The hospital transferred the body to the morgue for temporary storage while it was identified.','morgue 是存放遗体的设施，不是供人住宿的房间。','meaning'),[q('Why was the body transferred?','it was unidentified and investigators needed to identify it','it needed a hotel room','it was a fossil from a glacier','遗体身份不明，需要调查人员确认。'),q('What is a morgue used for?','temporary storage of corpses','monthly magazines','moped parking','morgue 用于暂时存放遗体。'),q('Which location is a morgue?','a hospital room holding bodies before identification','a ward where living patients sleep','a museum room displaying a stone monument','morgue 指遗体暂存场所。',1,'context'),q('From which language did morgue enter English?','French','Algonquian','Old English','morgue 借自法语。',1,'word-formation')]);
P('moribund','Moribund comes from Latin moribundus, “about to die,” from mori “to die”; it can describe a dying person or something close to collapse.',[C('moribund.s1','濒死状态','The veterinarian said the injured fox was moribund and arranged urgent treatment rather than leaving it in the field.','兽医说受伤的狐狸濒临死亡，于是安排紧急治疗，而不是把它留在野外。','The veterinarian said the injured fox was moribund / and arranged urgent treatment / rather than leaving it in the field.','moribund 作形容词指生命将尽、很可能活不下去。','兽医判断情况危急并安排紧急治疗。'),C('moribund.s2','濒死者','The nurse stayed beside the moribund man while his family arrived from the neighbouring town.','护士守在濒死男子身旁，直到他的家人从邻镇赶来。','The nurse stayed beside the moribund man / while his family arrived / from the neighbouring town.','the moribund 可名词化，指濒死的人。','moribund 直接修饰 man，所指为濒死者。')],M('The healthy, energetic patient was described as moribund even though doctors expected a full recovery.','The patient was described as moribund because doctors believed he was close to death.','预计完全康复与濒临死亡的判断相矛盾。','meaning'),[q('Why did the veterinarian arrange urgent care?','the fox was close to death','the fox had already joined its family','the animal was a monthly visitor','moribund 表示濒死，需紧急处理。',1),q('Who was the nurse beside?','a man close to death','a healthy athlete after a race','a city monument','第二例直接写 nurse 陪在濒死男子身旁。',2),q('Which institution could be called moribund figuratively?','a failing organisation close to collapse','a thriving company expanding quickly','a newly opened clinic','该词可比喻即将衰败的机构。',1,'word-choice'),q('Moribund is historically connected with Latin for?','dying','monthly','mountainous','词源来自表示“将死”的拉丁词。',1,'word-formation')]);
P('morn','Morn is an old poetic form related to morning, from Old English morgen; today it usually appears in verse or deliberately archaic style.',C('morn.s1','诗歌用词','At break of morn, the shepherd led the flock across the misty ridge before the sun warmed the valley.','清晨时分，牧羊人趁太阳尚未晒暖山谷，带着羊群穿过雾气笼罩的山脊。','At break of morn / the shepherd led the flock / across the misty ridge / before the sun warmed the valley.','morn 是较古雅、常见于诗歌的 morning 形式。','break of morn 是刻意带诗意的清晨表达。'),M('The office email used “at break of morn” as its usual modern business wording for a meeting at 3 p.m.','The poem says “at break of morn” to evoke the early morning in an archaic style.','morn 指早晨且风格古雅；下午商务邮件语境不合适。','register'),[q('When did the shepherd lead the flock?','early in the morning','at midnight','after sunset','太阳尚未晒暖山谷，说明是清晨。',1),q('What style does morn usually suggest?','poetic or archaic','technical medical','ordinary plural','morn 是古雅或诗歌用语。',1,'register'),q('Which phrase has a deliberately old-fashioned tone?','at break of morn','at three in the afternoon','on the first business day','morn 常用于带诗意的表达。',1,'context'),q('Morn is closely related in meaning to?','morning','morgue','moraine','morn 是 morning 的古雅形式。',1,'confusable')]);
P('morning','Morning is from Old English morgen and related Germanic forms; it names the part of the day before noon and can refer to the next day after a late night.',[C('morning.s1','一天中的上午','The library opens at nine in the morning, and the reading room closes shortly before noon.','图书馆上午九点开门，阅览室在中午前不久关闭。','The library opens at nine in the morning / and the reading room closes / shortly before noon.','morning 通常指从日出或醒来到中午的一段白天时间。','开门九点、关门接近正午，处于上午。'),C('morning.s2','熬夜后的次日','They worked through the night preparing the exhibit, then agreed to review the labels in the morning.','他们通宵布置展览，然后约好第二天早上检查标签。','They worked through the night preparing the exhibit / then agreed to review the labels / in the morning.','the morning 可相对于前一晚指紧接着的第二天早晨。','通宵之后的 morning 是下一日早晨。')],M('The library opened at nine in the morning, several hours after noon.','The library opened at nine in the morning, three hours before noon.','九点上午在正午之前，不是正午之后。','measurement'),[q('When does the library open?','at 9 a.m.','at 9 p.m.','at midnight','例句明确说上午九点开门。',1,'measurement'),q('When will they review the labels?','the morning after working through the night','during the previous afternoon','at the next midnight','in the morning 指通宵之后的次日早晨。',2,'context'),q('Which time is part of the morning?','10 a.m.','2 p.m.','10 p.m.','上午通常在中午之前，十点符合。',1,'measurement'),q('Morning usually ends around?','noon','midnight','sunset the next day','morning 指到中午前后的时段。',1,'meaning')]);
P('moron','Moron entered English from Greek mōros, “foolish,” through a former psychological classification; as an insult for a person it is rude and should be avoided.',C('moron.s1','冒犯性称呼','The editor removed the word moron from the profile because it insulted a resident instead of describing the resident’s actual decision.','编辑从人物介绍中删去 moron，因为它是在侮辱居民，而不是描述居民实际作出的决定。','The editor removed the word moron from the profile / because it insulted a resident / instead of describing the resident’s actual decision.','moron 是对人的粗鲁侮辱性称呼，不是中性的诊断词。','编辑以具体行为描述取代贬损标签。'),M('The reporter called the resident a moron as a respectful, neutral medical diagnosis.','The reporter described the resident’s specific mistake without using an insulting label.','moron 是粗鲁的侮辱语，不是中性或专业诊断。','register'),[q('Why did the editor remove moron?','it insulted the resident','it named a calendar month','it described a glacier deposit','编辑认为该词侮辱居民。'),q('How should a report describe the resident instead?','state the specific decision or behaviour','use another personal insult','invent a medical diagnosis','应描述具体行为而非贴侮辱性标签。'),q('What is the register of moron when applied to a person?','rude and insulting','formal and respectful','neutral and required','该词用来称人时有冒犯性。',1,'register'),q('The word historically entered English through a former?','psychological classification','monthly periodical','mountain survey','该词曾被用作心理学分类名称，后来转为辱骂语。',1,'word-formation')]);
P('morphological','Morphological is morphology plus -ical; morphology combines Greek morphē, “form,” with -logia, “study or account.”',C('morphological.s1','生物形态','The biologists used morphological traits, including leaf shape and stem arrangement, to distinguish the two closely related plants.','生物学家利用叶片形状和茎的排列等形态特征，区分这两种亲缘关系接近的植物。','The biologists used morphological traits / including leaf shape and stem arrangement / to distinguish the two closely related plants.','morphological 在生物学中指与生物形态或外部结构有关。','叶片与茎的形状排列是可比较的形态特征。'),M('The botanists called leaf shape a grammatical feature of the plant rather than a morphological trait.','The botanists called leaf shape a morphological trait of the plant.','植物叶片形状属于形态特征，不是语言语法特征。','word-choice'),[q('Which traits did the biologists compare?','leaf shape and stem arrangement','verb tense and sentence mood','monthly publication dates','叶片与茎的排列用于区分植物。'),q('In biology, morphological describes features of?','form or structure','ethical rules','a motor vehicle','morphological 指生物的形态或结构。'),q('Which is a morphological observation about a plant?','its leaves are narrow and arranged in pairs','its rent is due monthly','its stem is morally responsible','形状和排列是形态学观察对象。',1,'context'),q('Morphological is formed from morphology plus?','-ical','-less','-ment','morphological 以 -ical 构成形容词。',1,'word-formation')]);
P('morphology','Morphology combines Greek morphē, “form,” with -logia, “study”; it studies form and structure in organisms, landscapes, or language.',[C('morphology.s1','生物形态学','The ecologist compared the morphology of two island lizards, measuring their limb proportions and jaw shapes.','生态学家比较两种岛屿蜥蜴的形态，测量它们的四肢比例和颌部形状。','The ecologist compared the morphology of two island lizards / measuring their limb proportions / and jaw shapes.','生物学里的 morphology 指生物的形态结构及其研究。','四肢比例与颌部形状是生物结构特征。'),C('morphology.s1','语言构词结构','In English morphology, adding -ness to kind forms the noun kindness and changes the word’s grammatical role.','在英语词法中，kind 加上 -ness 构成名词 kindness，并改变词的语法作用。','In English morphology / adding -ness to kind forms the noun kindness / and changes the word’s grammatical role.','语言学中的 morphology 研究词的内部构造和构词变化。','后缀使形容词 kind 转为名词 kindness。')],M('The linguist called the study of how -ness forms kindness zoological morphology.','The linguist called the study of how -ness forms kindness English morphology.','词内部构造属于语言形态学，不是动物形态学。','distinction'),[q('What physical features did the ecologist measure?','limb proportions and jaw shapes','the lizards’ monthly rent','their verb endings','这些是蜥蜴的形态特征。',1),q('What does adding -ness do to kind?','forms the noun kindness','forms the plural moose','turns it into a verb meaning to climb','-ness 形成名词并改变词类。',1,'word-formation'),q('Which question belongs to linguistic morphology?','How does -ness turn an adjective into a noun?','What shape is a lizard’s jaw?','How does a glacier deposit gravel?','词的内部构造属于语言形态学。',1,'distinction'),q('Morphology broadly studies?','form and structure','only ethical behaviour','monthly time periods','morphology 研究形态和结构。')]);
P('morris','Morris is a shortened form of morris dance, historically glossed as “Moorish dance”; the reason for the English dance’s name is uncertain.',C('morris.s1','英国民间舞','The village troupe performed a morris in the square, stepping in time and shaking small bells tied around their legs.','村里的舞团在广场表演莫里斯舞，踩着节拍摇动绑在腿上的小铃铛。','The village troupe performed a morris in the square / stepping in time / and shaking small bells tied around their legs.','morris 指传统英国民间舞，舞者常穿传统服饰并配铃。','踏步和腿铃是莫里斯舞表演中的可见元素。'),M('The troupe called a silent chess match in ordinary clothes a morris, though nobody danced or wore costume.','The troupe performed a morris dance with rhythmic steps and bells.','morris 是舞蹈，不是静坐下棋。','meaning'),[q('What did the village troupe perform?','a traditional dance','a chess match','a monthly lecture','他们在广场表演传统舞蹈。'),q('What did dancers shake while stepping?','small bells tied around their legs','mortar bowls','ice samples','句中提到腿上绑的小铃铛。',1,'context'),q('Which setting best fits a morris?','a folk dance performed by a costumed troupe','a silent board game','a motor race on a motorway','morris 是民间舞蹈。',1,'distinction'),q('Why should the origin explanation be cautious?','the dance’s exact naming reason is uncertain','morris certainly means “mountain” in Latin','the word was formed from motor and pedal','该舞名虽与“Moorish dance”相关，确切命名原因仍不清楚。',1,'word-formation')]);
P('mortal','Mortal comes from Old French mortel and Latin mortalis, related to mors “death”; it describes beings subject to death, something deadly, or an ordinary human.',[C('mortal.s1','有死的生命','The myth reminds the king that even a powerful ruler is mortal and cannot live forever.','神话提醒国王，即使权势强大的统治者也是凡人，不能永生。','The myth reminds the king / that even a powerful ruler is mortal / and cannot live forever.','mortal 表示生命不能永恒、终将死亡。','国王无法永生，体现有死的属性。'),C('mortal.s2','致命后果','The surgeon treated a mortal wound immediately, knowing the injury could cause death without rapid care.','外科医生立即处理致命伤，因为他知道若不迅速救治，这种伤势可能导致死亡。','The surgeon treated a mortal wound immediately / knowing the injury could cause death / without rapid care.','mortal 作形容词也可表示会导致死亡的、致命的。','伤势若不及时处理可能致死。'),C('mortal.s3','凡人','In the legend, the goddess spoke to mortals who lived in the town below her mountain temple.','传说中，女神对住在山上神庙下方城镇里的凡人说话。','In the legend / the goddess spoke to mortals / who lived in the town below her mountain temple.','mortals 常作名词，指与神明相对的普通人。','神话把女神与城中人类凡人相对照。')],M('The legend called the immortal goddess mortal even though she could never die and was not human.','The legend called the townspeople mortal because, unlike the goddess, they could die.','不会死亡的神明不是 mortal；该词指终有一死者。'),[q('What can the powerful king not do?','live forever','treat a wound','speak to the town','mortal 表示不能永生。',1),q('Why was the wound treated immediately?','it could cause death','it was a monthly injury','it had formed a mountain','mortal wound 是可能致死的伤。',2),q('Who are the mortals in the legend?','ordinary human townspeople','the immortal goddess','the temple stones','mortals 指与神明相对的普通人。',3),q('Which meaning of mortal appears in mortal wound?','deadly','unable to live forever only','ordinary human','此处 mortal 表示致命的。',2,'distinction')]);
P('mortality','Mortality comes from Latin mortalitas, related to mortalis “mortal”; it can mean a population’s death rate or the fact that living beings must die.',[C('mortality.s1','死亡率','The report found that infant mortality fell after clean-water systems reached the remote districts.','报告发现，偏远地区接入清洁供水系统后，婴儿死亡率下降了。','The report found that infant mortality fell / after clean-water systems reached the remote districts.','mortality 可指一定地点和时期内的死亡人数或死亡率。','报告比较供水改善前后的婴儿死亡情况。'),C('mortality.s2','必死性','The play confronts human mortality through an old sailor who reflects on the limited time he has left.','这部戏通过一位思考余生有限的老水手，直面人类终有一死这一事实。','The play confronts human mortality / through an old sailor / who reflects on the limited time he has left.','human mortality 指人类必然会死亡这一事实。','水手反思余生有限，谈的是必死命运。')],M('The report called a fall from 8 to 3 infant deaths per 1,000 births a rise in mortality.','The report described the change from 8 to 3 infant deaths per 1,000 births as a fall in mortality.','从每千活产8例降至3例是下降，不是上升。','measurement'),[q('What happened to infant mortality after clean water arrived?','it fell','it doubled','it became a mountain','报告说婴儿死亡率下降。',1),q('What does the sailor reflect on?','the fact that his remaining life is limited','a monthly train timetable','the shape of a plant leaf','他思考的是余生有限、人终有一死。',2),q('Which sentence uses mortality as a statistic?','The district’s mortality rate declined over five years.','The sailor accepted his mortality.','The sculpture is a monument to courage.','rate 表明这里谈人口死亡数据。',1,'distinction'),q('Human mortality means that humans?','must eventually die','never age','are all doctors','mortality 的第二义是人必有一死。',2,'meaning')]);
P('mortar','Mortar comes through Old French mortier from Latin mortarium; it can be a binding mixture for masonry, a bowl for crushing, or the act of joining with the mixture.',[C('mortar.s1','砌筑材料','The mason spread fresh mortar between the bricks and checked that each course remained level as the wall rose.','泥瓦匠把新砂浆抹在砖块之间，并在墙体升高时检查每一层是否平整。','The mason spread fresh mortar between the bricks / and checked that each course / remained level as the wall rose.','mortar 作名词可指填在砖石之间的砂浆。','砂浆连接砖块并填补缝隙。'),C('mortar.s1','研磨器皿','The pharmacist crushed the dried leaves in a stone mortar before mixing the powder into the remedy.','药剂师把干叶放入石臼捣碎，再把粉末混入药剂。','The pharmacist crushed the dried leaves in a stone mortar / before mixing the powder / into the remedy.','mortar 也可指与杵配合研磨材料的碗状器皿。','石臼用于把干叶磨成粉。'),C('mortar.s2','用砂浆砌合','The workers mortared the garden wall carefully, filling every joint before the cold weather arrived.','工人在寒冷天气到来前仔细用砂浆砌好花园墙，填满每一道接缝。','The workers mortared the garden wall carefully / filling every joint / before the cold weather arrived.','mortar 作动词表示用砂浆砌合或覆盖砖石。','砂浆填入墙体接缝，完成砌筑。')],M('The mason joined the bricks with loose dry sand and called it mortar, although no binding material held them together.','The mason joined the bricks with mortar, a binding mixture of cement or lime, sand, and water.','单独的干砂不能像砂浆一样黏结砖块。','meaning'),[q('What held the bricks together?','fresh mortar','a stone pestle','a railway timetable','砖块间抹了砂浆。'),q('What did the pharmacist crush in the stone mortar?','dried leaves','brick courses','a moped pedal','石臼里捣碎的是干叶。',2,'context'),q('Which sentence uses mortar as a verb?','They mortared the wall joints.','They mixed powder in a mortar.','They spread mortar between bricks.','mortared 作动词表示用砂浆砌合。',2,'grammar'),q('A pharmacist’s mortar is a?','bowl for crushing ingredients','mixture between bricks','temporary suspension order','药剂师使用的 mortar 是研磨器皿。',2,'distinction')]);
P('mortgage','Mortgage came from Old French mort gage, literally “dead pledge”; a mortgaged property secures a loan, and mortgage can also be the verb for pledging it.',[C('mortgage.s1','住房贷款','The couple compared fixed-rate mortgage offers and checked the total interest before choosing a loan for their first home.','这对夫妇比较固定利率住房贷款方案，并核算总利息后，才为首套住房选定贷款。','The couple compared fixed-rate mortgage offers / and checked the total interest / before choosing a loan for their first home.','mortgage 作名词指以房产作担保、用于购房的贷款。','贷款由住房作担保，借款人需按约偿还。'),C('mortgage.s2','抵押房产','The farmer mortgaged part of the estate to borrow money for new irrigation equipment.','农场主抵押了部分地产，以借钱购买新的灌溉设备。','The farmer mortgaged part of the estate / to borrow money / for new irrigation equipment.','mortgage 作动词表示以财产向贷款方设定担保权益。','地产被用作借款担保。')],M('The bank issued a mortgage but had no legal claim on the house if the borrower failed to repay.','The bank secured the mortgage against the house, which it could claim if the borrower defaulted.','mortgage 的担保安排使贷款方在违约时可对抵押房产主张权利。','meaning'),[q('What did the couple compare?','fixed-rate home-loan offers','morris dance costumes','mortar bowls','他们比较固定利率住房贷款。',1),q('Why did the farmer mortgage the estate?','to borrow for irrigation equipment','to publish a monthly','to build a glacier','抵押地产为购买灌溉设备筹资。',2),q('Which sentence uses mortgage as a verb?','She mortgaged the farm to secure a loan.','She reviewed the mortgage terms.','The mortgage had a fixed rate.','mortgaged 是动词，表示拿财产作贷款担保。',2,'grammar'),q('Why is mortgage historically described as a “dead pledge”?','the pledge ends when the debt is repaid or the property is forfeited','the house is guaranteed to be demolished','the borrower never has to repay','词源说债务偿清或违约处置后，担保关系即告终结。',1,'word-formation')]);
P('mortify','Mortify comes from Old French mortifier and Latin mortificare, “to cause death”; its common modern sense is to cause extreme embarrassment.',C('mortify.s1','使窘迫羞愧','The presenter was mortified when the slide displayed her private notes to the entire conference hall.','幻灯片把她的私人备注显示给整个会场后，演讲者羞愧难当。','The presenter was mortified / when the slide displayed her private notes / to the entire conference hall.','mortify 的常见现代义是使某人极度难堪或羞愧。','私人备注被公开，令演讲者非常尴尬。'),M('The presenter was mortified by the mistake and felt completely proud and unembarrassed.','The presenter was mortified by the mistake and felt deeply embarrassed.','mortified 表示极度难堪，不是自豪且毫不尴尬。','meaning'),[q('Why was the presenter mortified?','her private notes appeared on the screen','the conference hall was empty','the slide showed a monthly calendar','私人备注在会场公开，令她极度难堪。'),q('To mortify someone is to make that person feel?','deeply embarrassed','physically taller','more distant from a city','mortify 的常见义是使羞愧难当。'),q('Which event would mortify a speaker?','a microphone broadcasts a private rehearsal mistake','the speaker receives a routine programme','the speaker arrives early unnoticed','公开播出私人失误会让演讲者十分窘迫。',1,'context'),q('Mortify historically contains a Latin element connected with?','death','month','mountain','其拉丁来源含“使死”的意思，后发展出使人难堪义。',1,'word-formation')]);
P('mortise','Mortise came through French mortaise; its deeper origin is uncertain. It names the cavity that receives a tenon and the act of cutting or using that joint.',[C('mortise.s1','榫孔','The carpenter cut a rectangular mortise in the door frame so the matching tenon would fit snugly.','木匠在门框上开出矩形榫孔，让对应的榫头紧密嵌入。','The carpenter cut a rectangular mortise in the door frame / so the matching tenon / would fit snugly.','mortise 作名词指接纳榫头的凹槽或榫眼。','榫头嵌入凹槽形成木工连接。'),C('mortise.s2','开榫连接','The joiner mortised the oak rail into the post instead of relying on visible screws.','细木工把橡木横档开榫接入立柱，而没有依靠外露螺钉。','The joiner mortised the oak rail into the post / instead of relying on visible screws.','mortise 作动词指开榫眼或用榫眼连接木件。','横档通过榫眼固定到立柱。')],M('The carpenter cut a projecting tenon on the door frame and called the projecting piece a mortise.','The carpenter cut a cavity in the frame for the projecting tenon; that cavity is the mortise.','mortise 是容纳榫头的凹槽，凸出的部分是 tenon。','confusable'),[q('What fits into the rectangular mortise?','a matching tenon','a visible screw only','a monthly issue','榫头嵌入榫孔。',1),q('How did the joiner connect the rail?','by mortising it into the post','by leaving it unattached','by gluing a glacier to it','横档通过开榫接入立柱。',2),q('Which part is the mortise?','the cavity receiving a tenon','the projecting tenon itself','the whole wooden door','mortise 指接纳榫头的槽孔。',1,'confusable'),q('Which verb phrase uses mortise correctly?','mortise a rail into a post','mortise a monthly on a shelf','mortise a moose across a road','mortise 可作动词，表示开榫眼并连接木件。',2,'grammar')]);
P('mosaic','Mosaic came through French mosaïque and Italian mosaico from Medieval Latin mosaicum opus, “work of the Muses”; it can be a tiled picture or a varied whole.',[C('mosaic.s1','镶嵌画','The conservator replaced three cracked blue tiles in the mosaic without disturbing the surrounding glass pieces.','修复师没有扰动周围玻璃片，便更换了镶嵌画中三块开裂的蓝色瓷片。','The conservator replaced three cracked blue tiles in the mosaic / without disturbing / the surrounding glass pieces.','mosaic 指用小块玻璃、石头或瓷片拼成的图画。','不同颜色的小片共同组成图像。'),C('mosaic.s2','多元组合','The neighbourhood is a mosaic of languages and traditions, with each community contributing to the shared street market.','这个街区是语言与传统交织的多元整体，每个社群都为共同的街市增添特色。','The neighbourhood is a mosaic of languages and traditions / with each community contributing / to the shared street market.','mosaic 可比喻由不同部分组成的整体。','多个社群保留差异又共同构成街区。')],M('The conservator called a single unbroken sheet of blue paint a mosaic made from hundreds of separate glass pieces.','The conservator called the picture a mosaic because it was assembled from many small coloured pieces.','一整片连续颜料没有由许多小块拼成。','meaning'),[q('What did the conservator replace?','three cracked blue tiles','three mortgage papers','a whole city neighbourhood','修复师更换镶嵌画中的三块蓝色瓷片。'),q('What makes the neighbourhood a mosaic figuratively?','many communities contribute distinct traditions','every resident speaks one language only','it is built from blue glass tiles','多种语言和传统组成多元整体。',2,'distinction'),q('Which artwork is a mosaic?','a picture assembled from small coloured stones','a single unbroken painted sheet','a photograph printed on paper','mosaic 的字面义是由小片拼成的图画。',1,'context'),q('The metaphorical mosaic emphasises?','different elements forming one whole','one element replacing all others','a loan secured by a house','比喻义强调多样部分组成一个整体。',2,'meaning')]);
P('mosque','Mosque entered English through French mosquée and Italian moschea, ultimately from Arabic masjid, “place of prostration.”',C('mosque.s1','伊斯兰礼拜场所','Worshippers removed their shoes before entering the mosque’s prayer hall, where the service leader stood at the front.','礼拜者进入清真寺礼拜大厅前脱下鞋子，带领礼拜者站在大厅前方。','Worshippers removed their shoes before entering the mosque’s prayer hall / where the service leader / stood at the front.','mosque 是穆斯林礼拜场所，常设有礼拜大厅。','礼拜者在大厅聚集并由领拜者带领。'),M('The guide said the mosque was a Christian monastery where monks held their daily service.','The guide said the mosque was a Muslim place of prayer with a prayer hall.','mosque 指穆斯林礼拜场所，不是基督教修道院。','distinction'),[q('Where did worshippers gather?','in the mosque’s prayer hall','in a railway carriage','inside a stone mortar','礼拜者进入清真寺礼拜大厅。'),q('What did worshippers do before entering?','removed their shoes','mortgaged the hall','opened a monthly issue','例句明确写他们先脱鞋。',1),q('A mosque is primarily a place of prayer for?','Muslims','morris dancers','astronomers','清真寺是穆斯林礼拜场所。',1,'distinction'),q('Which feature belongs to the described mosque?','a prayer hall with a leader at the front','a glacier moraine at the entrance','a motor race track','礼拜大厅及领拜者符合例句。',1,'context')]);
P('mosquito','Mosquito was borrowed from Spanish mosquito, a diminutive of mosca, “fly”; it names a small flying insect whose female bites and drinks blood.',C('mosquito.s1','蚊虫叮咬','The ranger wore long sleeves at dusk because mosquitoes gathered beside the wetland and bit exposed skin.','黄昏时护林员穿上长袖，因为蚊子聚集在湿地旁，会叮咬裸露的皮肤。','The ranger wore long sleeves at dusk / because mosquitoes gathered beside the wetland / and bit exposed skin.','mosquito 指会飞的小昆虫，雌蚊会叮咬并吸血。','湿地旁黄昏聚集、叮咬皮肤的是蚊虫。'),M('The ranger called a harmless stone beside the wetland a mosquito because it bit exposed skin.','The ranger called the small biting insect a mosquito.','石头不会飞也不会叮咬；蚊子是昆虫。','meaning'),[q('Why did the ranger wear long sleeves?','mosquitoes were biting near the wetland','the mosque service was starting','the moon was too bright','护林员防止蚊子叮咬。'),q('Which mosquito is described as the blood-sucker?','the female','the male only','the stone beside the wetland','雌蚊叮咬并吸血。',1,'distinction'),q('Where did mosquitoes gather?','beside the wetland at dusk','inside the mosque prayer hall','on a glacier ridge','例句指出黄昏时湿地旁蚊虫聚集。',1),q('Spanish mosca means?','fly','mortar','morning','mosquito 的西班牙语来源与 mosca“苍蝇”有关。',1,'word-formation')]);
P('moss','Moss continues Old English mos, a word also found in related Germanic languages; it names a small soft plant and, in some regions, wet ground covered with it.',[C('moss.s1','苔藓植物','A green layer of moss grew on the shaded stone steps where rainwater collected after each storm.','每次暴雨后雨水汇集在阴凉石阶上，那里长出一层绿色苔藓。','A green layer of moss grew on the shaded stone steps / where rainwater collected / after each storm.','moss 是常生长于潮湿石面或土壤上的小型柔软植物。','阴湿石阶是苔藓适生环境。'),C('moss.s2','苔藓湿地','The walkers crossed the northern moss on wooden boards because the ground was soft, wet, and easily damaged.','地面松软潮湿且容易被破坏，徒步者便沿木板穿过北部苔藓沼泽。','The walkers crossed the northern moss on wooden boards / because the ground was soft, wet, / and easily damaged.','部分地区的 moss 也可指覆盖苔藓的湿软沼地。','木板路穿过湿软地面，指地域义 moss。')],M('The botanist identified a smooth stripe of green paint on bare stone as moss, although no plant was growing there.','The botanist identified the soft green plant growing on the damp shaded stone as moss.','涂料不是苔藓植物；词义指植物本身或覆盖它的湿地。','meaning'),[q('Where did the green moss grow?','on shaded stone steps that collected rainwater','on a dry motorway','inside a mortar bowl','阴凉潮湿的石阶长出苔藓。',1),q('Why did walkers use boards across the northern moss?','the wet ground was soft and vulnerable','the plants were too tall to see','the area was a mosque','木板保护松软潮湿的地面。',2),q('Which moss sense refers to a wet landscape?','soft wet ground covered with moss','the small plant on one stone','a stone tool for crushing leaves','北部的湿地义指苔藓覆盖的软湿地面。',2,'distinction'),q('Moss is most likely to thrive on?','a damp shaded surface','a hot dry road','a clean metal roof in desert sun','潮湿阴凉的表面适合苔藓生长。',1,'context')]);
P('most','Most continues Old English mæst, the superlative of micel (“much”); it can mean nearly all, the greatest degree, or “very” as an intensifier.',[C('most.s1','大多数','Most of the survey forms were complete, although a few residents had left the final question blank.','大多数调查表都填写完整，不过少数居民漏答了最后一题。','Most of the survey forms were complete / although a few residents / had left the final question blank.','most of + 名词表示其中的大部分或绝大多数。','只有少数表格不完整，因此大多数已完成。'),C('most.s2','最高程度','Of the three routes, the mountain pass is most difficult in winter because drifting snow blocks its narrowest section.','三条路线中，山口冬季最难走，因为积雪会封住最窄路段。','Of the three routes / the mountain pass is most difficult in winter / because drifting snow blocks its narrowest section.','most + 形容词可构成最高级，表示程度最高。','三条路线中山口难度最大。'),C('most.s3','非常（正式）','It was most kind of the neighbours to bring hot food after the family returned from the hospital.','这家人从医院回来后，邻居送来热饭菜，实在非常体贴。','It was most kind of the neighbours / to bring hot food / after the family returned from the hospital.','most 可作较正式的加强语，意为“非常”。','most kind 加强了对邻居善意的评价。')],M('Most forms were complete even though only two out of a hundred had been filled in.','Most forms were complete because nearly all had been filled in.','两份/一百份远非大多数，不能据此说 most 已完成。','measurement'),[q('What happened to most survey forms?','they were complete','they were all blank','they were sent to a mosque','大多数表格填写完整，仅少数漏题。',1),q('Which route is most difficult?','the mountain pass','the riverside path','the paved city street','三条路线中山口冬季最难。',2),q('In It was most kind, most means?','very','nearly all neighbours','the least kind','此处 most 是正式加强语，意为非常。',3,'distinction'),q('Most of the forms means?','nearly all of them','exactly one form','none of them','most of 表示大部分。',1,'meaning')]);
P('most badly','Most badly is the analytic superlative of the adverb badly, identifying the poorest performance among three or more.',C('most badly.s1','副词最高级','Among the three teams, the visitors were most badly affected by the sudden water shortage because their tanks were empty.','三支队伍中，客队受突发缺水影响最严重，因为他们的水箱已经空了。','Among the three teams / the visitors were most badly affected / by the sudden water shortage / because their tanks were empty.','most badly affected 在三者中比较受影响的程度。','客队水箱已空，所以在三队中受影响最大。'),M('The visitors were most badly affected, although they alone had full tanks and lost no access to water.','The visitors were most badly affected because their tanks were empty.','水箱满且供水未断，不能支持受影响最严重的说法。','word-formation'),[q('Which group suffered most from the water shortage?','the visitors','the hosts with full tanks','the nearby shopkeepers','客队水箱空了，受到影响最严重。',1),q('Most badly is the superlative of?','badly','good','badness','most badly 比较程度，构成 badly 的最高级形式。',1,'word-formation'),q('How many groups are compared in the example?','three','one','twelve','among the three teams 明确比较三队。',1,'measurement'),q('Which phrase correctly selects the greatest degree of harm?','most badly affected among the teams','more badly affected than the worst','badly affected than all','最高程度可用 most badly affected。',1,'grammar')]);
P('mostly','Mostly is most plus -ly and means mainly, for the greatest part, or on most occasions.',C('mostly.s1','主要成分','The archive’s collection is mostly handwritten letters, with only a small number of printed notices from the same period.','档案馆的藏品主要是手写信件，同一时期的印刷通知只有少量。','The archive’s collection is mostly handwritten letters / with only a small number / of printed notices from the same period.','mostly 表示大部分由某事物构成，但允许存在少量例外。','信件占多数，通知只占少数。'),M('The archive was mostly handwritten letters even though every item in it was a printed notice.','The archive was mostly handwritten letters, with a few printed notices.','全是印刷通知与“主要是手写信件”相反。','meaning'),[q('What makes up most of the archive?','handwritten letters','printed notices only','monthly magazines only','档案藏品主要是手写信件。'),q('Are there any printed notices?','yes, a small number','no, the archive is empty','yes, every item is one','句中说只有少量印刷通知。',1),q('Mostly allows for?','a main part plus some exceptions','no exceptions at all','only one item in every case','mostly 表示大部分，不意味着百分之百全部。',1,'distinction'),q('Mostly is formed from most plus?','-ly','-ment','-less','mostly 是 most 加 -ly 构成的副词。',1,'word-formation')]);
P('mote','Mote continues Old English mot, “small particle,” of uncertain deeper origin; it usually names a tiny speck of dust visible in light.',C('mote.s1','微尘颗粒','A mote drifted through the sunbeam above the desk, visible only when the curtains were drawn back.','一粒微尘飘过书桌上方的阳光，只有拉开窗帘时才能看见。','A mote drifted through the sunbeam above the desk / visible only / when the curtains were drawn back.','mote 指非常微小的颗粒，常特指光线中可见的尘埃。','光束让原本难以察觉的微尘显现出来。'),M('The reader called a large stone rolling across the room a mote visible in a sunbeam.','The reader called a tiny speck of dust drifting in the sunbeam a mote.','大型石块不属于微小颗粒。','meaning'),[q('When could the mote be seen?','when sunlight crossed the room','only after the desk was removed','during a motorway race','阳光照出飘浮的微尘。'),q('A mote is most nearly?','a tiny particle','a heavy boulder','a monthly issue','mote 指微小颗粒。',1,'meaning'),q('Which scene contains a mote?','a dust speck floating in a beam of light','a large rock blocking a road','a bowl holding dried leaves','阳光中浮动的小尘点是 mote。',1,'context'),q('What is uncertain about mote?','its deeper etymological origin','whether dust can be small','whether sunlight exists','这个词更深层的词源尚不确定。',1,'word-formation')]);
P('motel','Motel blends motor and hotel; it names a roadside hotel designed for motorists, often with parking near each room.',C('motel.s1','公路住宿','The family chose a motel beside the highway because they could park the car directly outside their room.','这家人选择了高速公路旁的汽车旅馆，因为可以把车直接停在房间外。','The family chose a motel beside the highway / because they could park the car / directly outside their room.','motel 是面向驾车旅客的路边旅馆，常方便车辆停靠。','车可停在房门外是汽车旅馆的典型便利。'),M('The travellers called an overnight train compartment a motel, although guests could not drive to it or park beside their rooms.','The travellers booked a roadside motel with parking beside each guest room.','motel 是为驾车旅客设计的路边住宿；列车卧铺车厢不是汽车旅馆。','meaning'),[q('Where could the family park?','directly outside the room','inside the prayer hall','beside a glacier','汽车可停在房间外。'),q('A motel is especially intended for?','motorists travelling by road','people attending a mosque service','people studying plant leaves','motel 面向驾车旅客。',1,'context'),q('Which parts blend to form motel?','motor and hotel','month and hotel','moss and metal','motel 是 motor 与 hotel 的混成词。',1,'word-formation'),q('Which feature commonly distinguishes a motel?','parking close to guest rooms','a prayer hall at the front','a railway platform inside each room','车辆通常能停在房间附近。',1,'distinction')]);
P('moth','Moth continues Old English moððe; the deeper history is uncertain. Most moths fly at night, and clothes moth larvae feed on natural fibres.',[C('moth.s1','飞蛾','A moth circled the porch lamp after sunset, then disappeared into the garden when the light was switched off.','日落后，一只飞蛾绕着门廊灯飞，灯关掉后便消失在花园里。','A moth circled the porch lamp after sunset / then disappeared into the garden / when the light was switched off.','moth 是近似蝴蝶的飞虫，多数在夜间活动。','飞虫在日落后绕灯飞行。'),C('moth.s2','衣蛾害虫','The conservator placed the wool coat in a sealed bag after finding holes made by clothes moth larvae.','发现羊毛外套上有衣蛾幼虫蛀出的洞后，修复师把外套装进密封袋。','The conservator placed the wool coat in a sealed bag / after finding holes / made by clothes moth larvae.','clothes moth 指其幼虫会蛀食衣物的小型蛾类。','羊毛衣物被幼虫咬出洞。')],M('The conservator blamed clothes moth larvae for holes in the coat, although the garment was untouched and the larvae eat no fibres.','The conservator blamed clothes moth larvae for the holes in the wool coat.','衣蛾幼虫会取食天然纤维，能造成衣物破洞。','meaning'),[q('What did the moth do near the porch?','circled a lamp after sunset','ate the wool coat in daylight','built a mortar wall','例句说飞蛾日落后绕着门廊灯飞。',1),q('What caused holes in the wool coat?','clothes moth larvae','a porch lamp','a glacier','衣蛾幼虫会蛀食衣物纤维。',2),q('Which moth sense is associated with damaged clothes?','a small clothes moth whose larvae eat fibres','any bird that flies at night','a speck of dust in sunlight','造成衣物破洞的是衣蛾及其幼虫。',2,'distinction'),q('What is uncertain about the word moth?','its deeper etymological history','whether some moths fly at night','whether wool is a fibre','词的更深层词源尚不确定。',1,'word-formation')]);
P('mother','Mother continues Old English mōdor and a widespread Indo-European kinship word; it can mean a female parent, a source, or caring for someone excessively.',[C('mother.s1','女性家长','Her mother waited at the station with a spare coat because the forecast predicted an unusually cold evening.','天气预报说傍晚会异常寒冷，她母亲便带着一件备用外套在车站等她。','Her mother waited at the station / with a spare coat / because the forecast predicted an unusually cold evening.','mother 作名词指女性家长。','母亲为女儿准备外套并到站迎接。'),C('mother.s2','源头或母体','The research team called the original cell culture the mother of several later laboratory strains.','研究团队把原始细胞培养物称为后来几种实验室菌株的母体。','The research team called the original cell culture / the mother of several later laboratory strains.','mother 可比喻指产生或孕育其他事物的源头。','后续菌株由原始培养物发展而来。'),C('mother.s3','过度照料','He tried not to mother his adult daughter, allowing her to make her own travel plans and solve small problems herself.','他尽量不对成年女儿过度照料，让她自己安排旅行、解决小问题。','He tried not to mother his adult daughter / allowing her to make her own travel plans / and solve small problems herself.','mother 作动词可指像母亲一样照料，也可带“过分呵护”意味。','让成年女儿自己处理事务，避免过度照料。')],M('He mothered his adult daughter by insisting that she handle every decision alone and refusing all help.','He mothered his adult daughter by taking over her small decisions and refusing to let her act independently.','mother 作动词表示照料或包办；刻意拒绝照料不符合该义。','word-choice'),[q('Why did her mother wait at the station?','to bring a spare coat for the cold evening','to inspect a glacier','to publish a monthly','母亲担心天气变冷，带外套来接她。'),q('What was called the mother of later lab strains?','the original cell culture','the station coat','the daughter’s travel plan','原始培养物是后续菌株的来源。',2),q('What did he avoid doing to his adult daughter?','overprotecting her and taking over small tasks','giving her any weather information','letting her travel','mother 作动词可指过度照料。',3,'distinction'),q('Which use is figurative?','the mother of later laboratory strains','her mother waited at the station','he tried not to mother his daughter','原始培养物是衍生菌株的源头，属于比喻义。',2,'distinction')]);
P('mother side','Mother side is a transparent family phrase for relatives connected through one’s mother.',C('mother side.s1','母系亲属','On her mother side, the family had kept letters from relatives who settled near the coast three generations earlier.','她母系一方的家人一直保存着三代前定居在海岸附近的亲属来信。','On her mother side / the family had kept letters / from relatives who settled near the coast / three generations earlier.','mother side 指通过母亲一方形成的亲属关系。','来信来自母亲一方的远亲。'),M('The cousins were related through their father, but the family record placed them on the mother side.','The cousins were related through their mother, so they belonged to her mother side of the family.','通过父亲相连的是父系，不是母系。','distinction'),[q('Who wrote the preserved letters?','relatives who settled near the coast','the family’s mortgage lender','morris dancers','信件来自三代前定居海岸的亲属。'),q('Which relatives belong to someone’s mother side?','relatives connected through their mother','relatives connected only through their father','unrelated neighbours','mother side 指母亲一方的亲属。',1,'distinction'),q('If an aunt is the mother’s sister, she is on the?','mother side','motor side','moraine side','母亲的姐妹属于母系一方。',1,'context'),q('What does the phrase identify?','which branch of a family relatives come through','a kind of vehicle','a monthly publication','该短语区分家族亲属的母系分支。',1,'meaning')]);
P('motherland','Motherland combines mother and land and names a country someone regards as a homeland, often with an emotional or patriotic tone.',C('motherland.s1','祖国故土','Although she had lived abroad for years, the poet still called the island her motherland and wrote about its coast.','尽管在海外生活多年，诗人仍称那座岛为自己的祖国，并写下有关海岸的诗。','Although she had lived abroad for years / the poet still called the island her motherland / and wrote about its coast.','motherland 指出生或自认为归属的国家，语气常带感情色彩。','诗人虽长期旅居海外，仍认同故土。'),M('The traveller called a country she had never visited and felt no connection to her motherland.','The traveller called the country where she was born and felt she belonged her motherland.','motherland 表示有归属或情感认同的祖国，不是毫无关联的陌生国家。','word-choice'),[q('What did the poet call her island?','her motherland','a monthly','a moribund town','她把仍牵挂的岛屿称作祖国。'),q('How did she feel about the island after years abroad?','she still felt it was her homeland','she had never heard of it','she considered it a motor race','诗人仍认同岛屿故土。',1),q('Which country is most naturally called someone’s motherland?','a country where they feel they belong','a place they have never known and reject','any country containing a mosque','motherland 常带出生地或归属感。',1,'context'),q('The compound combines mother with?','land','mood','mould','motherland 由 mother 与 land 构成。',1,'word-formation')]);
P('motherly','Motherly is mother plus -ly and describes behaviour or warmth like that of a kind, caring mother.',C('motherly.s1','温柔关怀','The neighbour gave the frightened child a motherly smile and waited with him until his parents arrived.','邻居向受惊的孩子露出慈母般的微笑，并陪他等到父母赶来。','The neighbour gave the frightened child a motherly smile / and waited with him / until his parents arrived.','motherly 作形容词表示像慈爱母亲一样温柔关怀。','微笑并耐心陪伴孩子体现照料与安慰。'),M('The neighbour gave the frightened child a motherly smile while mocking him and refusing to stay until help arrived.','The neighbour gave the frightened child a motherly smile and stayed to comfort him.','嘲笑并拒绝陪伴与温柔关怀的语义相反。','meaning'),[q('How did the neighbour comfort the child?','with a kind smile and company','by leaving immediately','by calling him moron','邻居微笑并留下陪伴受惊的孩子。'),q('Motherly most nearly means?','warm and caring like a kind mother','strictly legal','related to a motorway','motherly 描述慈爱温柔的照料方式。',1),q('Which action seems motherly?','waiting with a frightened child until family arrives','mocking a child and walking away','closing a clinic without notice','耐心陪伴受惊孩子体现关怀。',1,'context'),q('Motherly is formed by adding which suffix to mother?','-ly','-ment','-ness','motherly 由 mother 加 -ly 构成。',1,'word-formation')]);
P('motif','Motif came from French motif, “motive or design,” from Latin motivus; it is a short idea, image, or pattern repeated in music or art.',C('motif.s1','艺术反复主题','A recurring bird motif appears in the novel’s chapter titles and in the mural painted above the theatre entrance.','小说各章标题以及剧院入口上方的壁画中反复出现鸟的主题图案。','A recurring bird motif appears in the novel’s chapter titles / and in the mural / painted above the theatre entrance.','motif 指作品中反复出现的短主题、形象或图案。','鸟形象在标题和壁画中重复出现。'),M('The critic called a single unrelated bird mentioned once a recurring motif that shaped the whole novel.','The critic called the bird a motif because it recurred in titles and artwork.','只出现一次且无关联的细节不能称为反复主题。','meaning'),[q('Where did the bird motif recur?','in chapter titles and the theatre mural','only in a monthly payment','on a motorway sign once','鸟主题图案在章节标题与壁画中反复出现。'),q('A motif in art is often?','a repeated image or idea','a mortgage loan','a type of moss','motif 指重复出现的形象或主题。',1,'context'),q('Which detail is a motif?','a repeated key image connecting several scenes','a single accidental word with no recurrence','a tool used to grind herbs','跨场景反复出现的形象构成 motif。',1,'distinction'),q('Motif entered English through which language?','French','Algonquian','Old English only','motif 借自法语。',1,'word-formation')]);
P('motion','Motion comes from Old French motion and Latin motio, from movere “to move”; it can mean movement, a gesture, a formal proposal, or signalling by movement.',[C('motion.s1','物体运动','The sensor recorded the motion of the pendulum as it swung back and forth beneath the clock.','传感器记录了钟下摆锤来回摆动的运动。','The sensor recorded the motion of the pendulum / as it swung back and forth / beneath the clock.','motion 指位置变化或移动的过程。','摆锤位置来回变化，传感器记录其运动。'),C('motion.s2','身体动作','With one motion of her hand, the conductor brought the orchestra to a sudden stop.','指挥只用一个手势就让乐队突然停下。','With one motion of her hand / the conductor brought the orchestra / to a sudden stop.','motion 也可指一次具体的身体动作或手势。','手部动作传达停止演奏的信号。'),C('motion.s3','正式动议','The councillor introduced a motion to extend library opening hours, and members debated it before voting.','议员提出延长图书馆开放时间的动议，成员们先辩论再投票。','The councillor introduced a motion / to extend library opening hours / and members debated it before voting.','motion 作名词可指在会议上讨论并表决的正式提议。','动议经辩论后进入投票程序。'),C('motion.s4','打手势示意','The usher motioned the late arrivals toward the rear seats without interrupting the performance.','引座员用手势示意迟到者走向后排，没有打断演出。','The usher motioned the late arrivals / toward the rear seats / without interrupting the performance.','motion 作动词表示用手或头部动作示意某人做事。','引座员通过动作指引座位。')],M('The council introduced a motion, meaning a pendulum’s physical swing, and debated it before voting.','The council introduced a motion, a formal proposal to extend library hours.','会议讨论和投票的是正式提议，不是物体移动。','distinction'),[q('What movement did the sensor record?','the pendulum swinging back and forth','the council’s vote count only','the usher’s monthly salary','传感器记录摆锤往返摆动。',1),q('How did the conductor stop the orchestra?','with a hand gesture','by proposing longer library hours','by measuring a glacier','指挥用一个手势让乐队停止。',2),q('What did the councillor ask members to debate and vote on?','a proposal to extend library hours','a pendulum’s swing','a row of mosque seats','motion 作名词指正式动议。',3,'distinction'),q('What did the usher motion the late arrivals to do?','go toward the rear seats','introduce a proposal','swing beneath a clock','motion 作动词表示以动作示意他们去后排。',4,'grammar')]);
P('motionless','Motionless combines motion and -less and means completely still, without movement.',C('motionless.s1','完全静止','The deer remained motionless beside the trail until the hikers passed and the forest grew quiet again.','鹿在小径旁一动不动，直到徒步者走过、森林重新安静下来。','The deer remained motionless beside the trail / until the hikers passed / and the forest grew quiet again.','motionless 表示完全没有移动。','动物静止不动，等待人群离开。'),M('The deer was motionless while running rapidly across the trail and changing position every second.','The deer was motionless while standing still beside the trail.','快速奔跑、不断改变位置并非静止。','meaning'),[q('How did the deer behave as hikers passed?','it stayed completely still','it ran across the trail','it motioned them to sit','motionless 表示一动不动。'),q('What does the suffix -less contribute?','the absence of movement','a greater degree of movement','a person who moves','-less 表示没有 motion。',1,'word-formation'),q('Which object is motionless?','a statue fixed in place','a pendulum swinging back and forth','a moving motorcycle','固定的雕像没有运动。',1,'context'),q('Motionless is closest in meaning to?','still','mobile','motivated','motionless 意为静止的。',1,'confusable')]);
P('motivate','Motivate is formed from motive plus -ate; it means to give someone a reason or drive to act, or to be the reason that prompts an action.',[C('motivate.s1','激励行动','The tutor used short weekly goals to motivate the students to revise a little instead of cramming before the exam.','导师用每周的小目标激励学生一点点复习，而不是考前临时抱佛脚。','The tutor used short weekly goals / to motivate the students to revise a little / instead of cramming before the exam.','motivate someone to do 表示促使或激励某人采取行动。','明确的小目标推动学生持续复习。'),C('motivate.s2','构成行动原因','A desire to protect the wetlands motivated the residents to oppose the proposed road through the marsh.','保护湿地的愿望促使居民反对穿过沼泽的拟建公路。','A desire to protect the wetlands / motivated the residents / to oppose the proposed road through the marsh.','motivate 也可指某种原因推动某人作出决定。','保护湿地的愿望是居民反对道路的动因。')],M('The tutor motivated the students to revise by making them less willing to study and giving them no goals.','The tutor motivated the students to revise by setting manageable weekly goals.','缺少目标且降低学习意愿不会起到激励作用。','meaning'),[q('What helped students keep revising?','short weekly goals','a closed motorway','a moribund library','每周小目标激励学生持续复习。',1),q('What motivated residents to oppose the road?','a desire to protect wetlands','a wish to drain the marsh','a monthly magazine','保护湿地的愿望推动居民反对道路。',2),q('Which sentence uses motivate to name a cause?','Fear of flooding motivated the town to improve drainage.','The coach motivated the players with praise.','She felt motionless after the walk.','主语 Fear 是促成行动的原因。',1,'distinction'),q('Which pattern appears in motivate the students to revise?','motivate + person + to-infinitive','motivate + person + of + noun','motivate + person + at + verb-ing','常见结构是 motivate someone to do something。',1,'grammar')]);
P('motivation','Motivation is motive plus -ation and names the reason and inner drive behind an action.',C('motivation.s1','行动动力','Her motivation for learning medical English was to speak directly with patients during the rural clinic placement.','她学习医学英语的动力，是在乡村诊所实习时能直接与患者交流。','Her motivation for learning medical English / was to speak directly with patients / during the rural clinic placement.','motivation 指促使某人采取某种行为的原因或内在动力。','直接与患者沟通是她持续学习的目的。'),M('Her motivation for learning came from having no reason to study and no desire to use English.','Her motivation for learning came from wanting to communicate with patients.','缺少理由和意愿并不构成推动学习的动力。','meaning'),[q('Why did she study medical English?','to speak directly with patients','to repair the clinic roof','to translate a motor race','直接与患者交流是她学习的原因。'),q('Motivation includes a reason and?','drive to act','a mountain ridge','a grammar mood','motivation 包含促使行动的动力。',1),q('Which is a learner’s motivation?','a goal that gives them a reason to practise','a list of unrelated vocabulary','a monthly bill with no purpose','能促使练习的目标是学习动力。',1,'context'),q('Motivation is formed from motive plus?','-ation','-less','-ous','motivation 由 motive 加 -ation 构成名词。',1,'word-formation')]);
P('motivational','Motivational is motivation plus -al and describes something that encourages a person to act or persist.',C('motivational.s1','激励作用','The coach played a motivational recording before the final relay, reminding runners how their training had prepared them.','决赛接力前，教练播放了一段激励性录音，提醒选手训练如何让他们做好准备。','The coach played a motivational recording / before the final relay / reminding runners how their training had prepared them.','motivational 描述能鼓舞或促使人采取行动的事物。','录音鼓励选手坚持并投入比赛。'),M('The coach called the recording motivational even though it told the runners to give up and stop trying.','The coach called the recording motivational because it encouraged the runners to keep going.','劝人放弃不具备鼓舞行动的作用。','meaning'),[q('When did the coach play the recording?','before the final relay','after the motorway closed','during a monthly rent payment','录音在决赛接力前播放。'),q('What did the recording remind runners of?','their preparation through training','the shape of a mortar bowl','a family’s mother side','录音提醒选手训练使他们做好准备。'),q('A motivational speech is intended to?','encourage people to act or persist','make a place motionless','describe a mortgage rate','motivational 指能鼓舞行动或坚持。',1,'context'),q('Motivational is the adjective related to?','motivation','motive-less','mortar','motivational 与 motivation 同源，表示有激励作用的。',1,'word-formation')]);
P('motive','Motive came through Old French motif from Latin motivus, “moving”; it can mean a reason for an action or a recurring artistic idea.',[C('motive.s1','行为动机','Investigators found no clear motive for the theft, although the suspect had entered the office shortly before closing.','调查人员没有找到盗窃案的明确动机，尽管嫌疑人在关门前不久进过办公室。','Investigators found no clear motive for the theft / although the suspect had entered the office / shortly before closing.','motive 指促使某人采取行动的原因，常用于调查犯罪。','进入办公室的事实并未单独证明盗窃动机。'),C('motive.s2','艺术主题动机','A rising three-note motive returns whenever the hero enters, linking separate scenes in the score.','每当主人公登场，一个上行的三音动机便再次出现，把配乐中不同场景联系起来。','A rising three-note motive returns whenever the hero enters / linking separate scenes / in the score.','motive 在音乐或艺术中也可指反复出现的短主题。','三音主题在多处重现，形成结构关联。')],M('The detective claimed the suspect’s motive was proven only by the fact that he had once entered the office.','The detective treated the office entry as evidence but continued investigating the suspect’s reason for stealing.','行动机会本身不能确定行为背后的动机。','distinction'),[q('What did investigators lack?','a clear reason for the theft','a list of relay runners','a musical score','他们尚无明确盗窃动机。'),q('What musical idea returns with the hero?','a rising three-note theme','a mortgage payment','a moth at a lamp','短促的三音主题反复出现。',2),q('Which use is artistic rather than psychological?','a recurring musical motive','a suspect’s motive for theft','a reason for leaving early','音乐中反复主题属于艺术义。',1,'distinction'),q('A motive for an action is its?','underlying reason','physical movement only','monthly schedule','motive 指行动背后的原因。',1,'meaning')]);
P('motley','Motley came through Anglo-French motteley; its deeper origin is uncertain. It describes varied colours or kinds and formerly named a jester’s multicoloured costume.',[C('motley.s1','杂色多样','A motley crowd gathered outside the station, mixing musicians, market sellers, schoolchildren, and visiting researchers.','车站外聚集着形形色色的人，包括音乐家、摊贩、学生和来访研究人员。','A motley crowd gathered outside the station / mixing musicians, market sellers, schoolchildren, / and visiting researchers.','motley 可形容颜色或类型杂多、缺少统一秩序。','不同职业和身份的人构成多样人群。'),C('motley.s2','小丑彩衣','The museum displayed a jester’s motley beside a portrait showing its bright patches of contrasting fabric.','博物馆在一幅肖像旁展出弄臣的彩衣，肖像描绘了服装上色彩对比鲜明的拼布。','The museum displayed a jester’s motley / beside a portrait / showing its bright patches of contrasting fabric.','motley 作名词可指历史上弄臣穿的杂色服装。','拼接的鲜艳布片是传统彩衣的特点。')],M('The editor called a uniform group dressed in identical grey coats a motley crowd.','The editor called the crowd motley because it included people of many different kinds.','清一色相同服装的人群缺少 motley 所强调的多样性。','meaning'),[q('Who gathered outside the station?','a varied mix of people','one identical marching unit','a single jester only','人群由多个职业和身份的人构成。'),q('What was displayed beside the portrait?','a jester’s multicoloured costume','a motor engine','a stone mortar','博物馆展出弄臣的杂色服装。',2),q('Which use is a noun?','the jester’s motley','a motley crowd','a motley pattern','名词 motley 可指弄臣穿的彩衣。',1,'grammar'),q('What is known about motley’s deeper origin?','it is uncertain','it certainly comes from motor and hotel','it means “mother land” in Greek','该词更深层词源尚不确定。',1,'word-formation')]);
P('motor','Motor comes from Latin motor, “mover,” from movere “to move”; it names an engine, describes motor vehicles, and informally can mean a car in British English.',[C('motor.s1','动力机器','The electric motor turned the pump steadily, sending clean water from the storage tank to the upper floors.','电动机平稳地带动水泵，把净水从储水箱送到楼上。','The electric motor turned the pump steadily / sending clean water / from the storage tank to the upper floors.','motor 作名词指把电力或燃料转化为运动的机器。','电动机驱动水泵完成输送。'),C('motor.s2','机动车相关','The council approved a motor access lane beside the station so delivery vehicles would not block the bus entrance.','市议会批准在车站旁设置机动车通道，避免送货车辆堵住公交入口。','The council approved a motor access lane beside the station / so delivery vehicles / would not block the bus entrance.','motor 可作形容词，表示与发动机车辆有关。','该通道供送货机动车使用。'),C('motor.s3','汽车（英式口语）','He left his motor at the garage overnight and walked home after the mechanic found a leaking brake line.','技工发现制动管漏液后，他把车留在修车厂过夜，自己步行回家。','He left his motor at the garage overnight / and walked home / after the mechanic found a leaking brake line.','英国旧式或非正式用法中，motor 可指汽车。','需维修而留在车库的是他的汽车。')],M('The mechanic wrote “the motor failed” but explained that motor meant the whole car, not its engine.','The mechanic wrote “the motor failed,” using motor for the engine that powers the car.','motor 可指发动机；此处 failed 指发动机故障，而非整辆车失效。','distinction'),[q('What did the electric motor power?','the water pump','the bus entrance','a jester’s costume','电动机带动水泵输水。'),q('What kind of lane did the council approve?','a lane for motor vehicles','a lane for moths','a lane for monthly magazines','motor 作形容词修饰机动车通道。',2,'context'),q('In the British informal sentence, what did he leave at the garage?','his car','only a small engine part','a pump','此处 motor 指汽车本身。',3,'distinction'),q('Which statement best separates motor senses?','It can mean an engine, vehicle-related, or informally a car.','It only means a road.','It is always a verb meaning to motivate.','该词既可指发动机，也可作机动车相关形容词或口语中的汽车。',1,'distinction')]);
P('motor race','Motor race combines motor and race and names a competition in which motor vehicles race against one another.',C('motor race.s1','赛车赛事','Spectators watched the motor race from behind the barriers as the cars completed their final lap around the circuit.','观众隔着护栏观看赛车，车手们完成了环形赛道上的最后一圈。','Spectators watched the motor race from behind the barriers / as the cars completed / their final lap around the circuit.','motor race 指机动车之间的竞速比赛。','汽车在赛道上争先并完成最后一圈。'),M('The announcer called a footrace between runners on the beach a motor race, although no vehicle took part.','The announcer called the competition a motor race because cars raced around the circuit.','没有机动车参赛的跑步比赛不是 motor race。','meaning'),[q('What did spectators watch?','cars racing around a circuit','runners crossing a beach','morris dancers in a square','赛车手在环形赛道上竞速。'),q('Where did spectators stand?','behind the barriers','inside the moving cars','on the prayer-hall roof','观众在护栏后观看。'),q('Which event is a motor race?','cars competing for the fastest circuit time','a walking tour of a motorway','a race between two moths','机动车竞速符合 motor race 的含义。',1,'context'),q('What two ideas form motor race?','motor vehicle and competition','mother and land','moss and rainfall','motor race 指机动车参加的比赛。',1,'word-formation')]);
P('motorcycle','Motorcycle developed from motor plus cycle; it is a two-wheeled motor vehicle and can also refer to travelling by one.',[C('motorcycle.s1','摩托车','The mechanic checked the motorcycle’s tyres and lights before the rider set off on the mountain road.','骑手出发走山路前，技工检查了摩托车的轮胎和车灯。','The mechanic checked the motorcycle’s tyres and lights / before the rider set off / on the mountain road.','motorcycle 作名词指供一至两人乘坐的两轮机动车。','轮胎和车灯是车辆出发前的检查项目。'),C('motorcycle.s2','摩托出行','The island has narrow lanes, so many residents prefer motorcycle for short trips between villages.','岛上道路狭窄，因此许多居民更喜欢骑摩托车在村庄间短途出行。','The island has narrow lanes / so many residents prefer motorcycle / for short trips between villages.','motorcycle 也可表示以摩托车作为出行方式。','这里 motorcycle 不指某一辆车，而指这种交通方式。')],M('The rider set off on a motorcycle, which the guide identified as a four-wheeled car with an enclosed cabin.','The rider set off on a motorcycle, a two-wheeled motor vehicle.','摩托车通常是两轮机动车，不是封闭式四轮汽车。','distinction'),[q('What did the mechanic check?','the motorcycle’s tyres and lights','a mortar’s stone surface','the rider’s monthly rent','技工检查摩托车的轮胎和车灯。'),q('Why do island residents prefer motorcycle for short trips?','the lanes are narrow','the island has a motorway in every field','the cars are all motionless','狭窄道路适合摩托车短途通行。',2,'context'),q('Which use refers to a way of travelling rather than one vehicle?','They prefer motorcycle for short village trips.','She repaired the motorcycle’s headlight.','The motorcycle is parked outside.','第二例泛指骑摩托出行这一方式。',2,'distinction'),q('A motorcycle usually has?','two wheels and a motor','four wheels and no engine','a prayer hall','摩托车是两轮机动车。',1,'meaning')]);
P('motorway','Motorway combines motor and way and is the British English term for a major high-speed road between towns or cities.',C('motorway.s1','英国高速公路','The motorway was closed after a lorry overturned, so drivers followed the signed diversion through nearby villages.','一辆货车翻倒后高速公路封闭，司机们便按路牌经附近村庄绕行。','The motorway was closed after a lorry overturned / so drivers followed / the signed diversion through nearby villages.','motorway 是英国英语中的多车道高速公路用语。','因交通事故封闭并设置绕行路线的道路是高速公路。'),M('The sign directed drivers onto the motorway, a narrow farm path with no lanes for fast traffic.','The sign directed drivers onto the motorway, a major road designed for fast travel.','狭窄农道不是供快速城际交通使用的 motorway。','meaning'),[q('Why was the motorway closed?','a lorry had overturned','a mosque service had ended','a moth circled a lamp','货车翻倒导致道路关闭。'),q('Where did drivers go instead?','through nearby villages on a signed diversion','onto the overturned lorry','inside the motorway office','司机按路牌经附近村庄绕行。',1),q('Motorway is the usual British term for?','a major high-speed road','a two-wheeled vehicle','a monthly magazine','motorway 指主要高速公路。',1,'distinction'),q('The compound motorway contains motor and?','way','mood','mote','motorway 由 motor 与 way 构成。',1,'word-formation')]);
P('mottle','Mottle probably developed as a back-formation from motley; as a verb it means to mark with irregular patches, and as a noun it is a blotch.',[C('mottle.s1','使呈斑驳','Cloud shadows mottled the hillside as sunlight moved across the broken layer of afternoon clouds.','午后云层散开，阳光移动时，云影使山坡呈现斑驳色块。','Cloud shadows mottled the hillside / as sunlight moved / across the broken layer of afternoon clouds.','mottle 作动词表示使表面出现深浅不一的不规则斑块。','云影在山坡上形成不均匀色块。'),C('mottle.s2','斑点','A pale mottle on the ceramic bowl showed where the glaze had cooled unevenly in the kiln.','陶碗上的一块浅色斑点显示釉料在窑中冷却不均。','A pale mottle on the ceramic bowl / showed where the glaze / had cooled unevenly in the kiln.','mottle 作名词指不规则颜色斑块。','釉面上单个浅色斑点是 mottle。')],M('The potter called the bowl mottled, although its glaze was perfectly uniform with no marks or patches.','The potter noted a pale mottle where the glaze had cooled unevenly.','没有任何颜色变化或斑点的表面并非斑驳。','meaning'),[q('What created the patchy hillside?','moving cloud shadows','a mortar joint','a monthly report','云影在山坡上形成深浅不同的色块。'),q('What did the pale mottle reveal?','the glaze cooled unevenly','the bowl was made of moss','the motorway had closed','浅色斑点显示釉料冷却不均。',2),q('Which sentence uses mottle as a verb?','Clouds mottled the hillside.','A mottle marked the bowl.','The bowl had one mottle.','mottled 是动词，表示使呈斑驳。',1,'grammar'),q('As a noun, a mottle is?','an irregular patch of colour','a fast road','a verbal proposal','名词 mottle 指不规则颜色斑块。',2,'distinction')]);
P('mottled','Mottled is the past participle of mottle and describes something covered with irregular spots or streaks.',C('mottled.s1','斑驳表面','The mottled shell had brown and cream patches that helped it blend into the pebbles along the shore.','这只斑驳的贝壳带有棕色和奶油色斑块，能融入岸边的卵石中。','The mottled shell had brown and cream patches / that helped it blend / into the pebbles along the shore.','mottled 作形容词表示表面有不规则斑点或条纹。','贝壳上的杂色斑块有伪装作用。'),M('The shell was described as mottled even though its surface was a single, perfectly even colour.','The shell was described as mottled because brown and cream patches covered it.','单一均匀颜色没有 mottled 所需的不规则斑纹。','meaning'),[q('Which colours appeared on the shell?','brown and cream','blue and silver only','red and black stripes','例句提到棕色和奶油色斑块。'),q('How did the shell blend in?','its patches matched the pebbles','it became motionless','it turned into a motorway','杂色斑块帮助它融入卵石。',1),q('A mottled surface has?','irregular spots or streaks','one perfectly uniform shade','no visible surface','mottled 描述不规则斑点或条纹。',1,'meaning'),q('Mottled is formed from which verb?','mottle','moralize','motivate','mottled 是动词 mottle 的过去分词形式。',1,'word-formation')]);
P('motto','Motto came through Italian motto, “word or saying,” from Latin muttum, “utterance”; it is a short statement expressing a guiding principle.',C('motto.s1','格言宗旨','The school’s motto, “Learn boldly, serve kindly,” appears above the entrance and guides its community projects.','学校的格言“勇于学习，友善服务”写在入口上方，也指导着社区项目。','The school’s motto / “Learn boldly, serve kindly,” / appears above the entrance / and guides its community projects.','motto 是表达组织或个人指导原则的简短句子。','格言不仅展示在入口处，也用于指导行动。'),M('The school called a ten-page timetable listing every lesson its motto, although it stated no guiding principle.','The school called “Learn boldly, serve kindly” its motto because it expressed a guiding principle.','详细课表不是表达原则的简短格言。','meaning'),[q('What is the school’s motto?','“Learn boldly, serve kindly.”','“The entrance is above the hall.”','“The motorway closes at dusk.”','学校格言是勇于学习、友善服务。'),q('Where does the motto appear?','above the entrance','inside a mortar bowl','on a moth’s wing','格言写在入口上方。'),q('Which phrase is a motto?','a short statement expressing a guiding value','a complete monthly attendance spreadsheet','a list of motor parts','简短指导原则符合 motto 的定义。',1,'context'),q('Motto entered English through?','Italian','Algonquian','Old English','motto 经意大利语进入英语。',1,'word-formation')]);
P('mould','British mould corresponds to American mold; the shaping sense came through French from Latin modulus, while the fungus sense has a separate, less certain history.',[C('mould.s1','模具与霉菌','The jelly set in a flower-shaped mould, while a patch of mould on the damp cupboard wall had to be cleaned.','果冻在花形模具中凝固；潮湿橱柜墙上的一块霉菌则需要清理。','The jelly set in a flower-shaped mould / while a patch of mould / on the damp cupboard wall had to be cleaned.','mould 可指塑形容器，也可指潮湿物体上生长的绒状真菌。','同一句展示两个同拼写、不同含义的名词。'),C('mould.s2','塑造或影响','Years of fieldwork moulded the young scientist into a careful observer who recorded every change in the wetland.','多年的实地工作把这位年轻科学家塑造成谨慎的观察者，使她记录湿地的每一处变化。','Years of fieldwork moulded the young scientist / into a careful observer / who recorded every change in the wetland.','mould 作动词既可把材料塑成形，也可比喻塑造人的性格。','经历影响并形成了她细致的观察习惯。')],M('The baker poured jelly into a mould, meaning the fuzzy fungus growing on damp food.','The baker poured jelly into a shaped container called a mould.','塑形容器与潮湿处生长的真菌是 mould 的不同义项。','confusable'),[q('Where did the jelly set?','in a flower-shaped container','on the damp cupboard wall','inside the scientist’s notebook','果冻在花形模具中凝固。',1),q('What did fieldwork do to the scientist?','shaped her into a careful observer','covered her with fungus','turned her into a motor','mould 作动词可比喻塑造人的性格。',2),q('Which mould is the fuzzy fungus?','the patch on the damp cupboard wall','the flower-shaped jelly container','the scientist’s careful habit','潮湿墙上的斑块是真菌义。',1,'distinction'),q('Which expression uses mould figuratively?','experience moulded her character','jelly set in a mould','mould grew on the wall','经历塑造性格是比喻用法。',1,'distinction')]);
P('mouldy','Mouldy is mould plus -y and means covered or spoiled by fungus; figuratively it can mean old-fashioned and dull.',[C('mouldy.s1','发霉变质','The baker discarded the mouldy bread after finding green patches inside the sealed paper bag.','面包师发现纸袋里长出绿色斑点后，丢弃了发霉的面包。','The baker discarded the mouldy bread / after finding green patches / inside the sealed paper bag.','mouldy 表示因真菌生长而发霉、变质。','绿色菌斑使面包不宜食用。'),C('mouldy.s1','陈腐乏味','The editor rejected the mouldy joke because readers had heard the same tired punchline for decades.','编辑拒绝了这个陈腐的笑话，因为读者几十年来听过同样乏味的包袱。','The editor rejected the mouldy joke / because readers had heard / the same tired punchline for decades.','mouldy 可比喻陈旧、乏味而缺乏新意。','笑话多年重复，显得过时无趣。')],M('The baker served the bread as mouldy even though it was freshly baked, clean, and free of fungal growth.','The baker discarded the bread after green mould appeared inside the bag.','没有真菌生长且新鲜的面包不应称为发霉。','meaning'),[q('Why was the bread discarded?','green mould had appeared','it was a monthly magazine','it had become motionless','面包出现绿色霉斑。',1),q('Why was the joke called mouldy?','it was stale and had been repeated for decades','it had grown green fungus','it was a new original idea','比喻义表示笑话陈旧乏味。',1),q('Which use is figurative?','a mouldy old joke','mouldy bread with green patches','mouldy fruit in a bin','笑话过时乏味是比喻用法。',1,'distinction'),q('Mouldy is formed by adding -y to?','mould','motive','mound','mouldy 由 mould 加 -y 构成。',1,'word-formation')]);
P('mound','Mound is recorded in Middle English for a raised bank or heap; its deeper origin is uncertain and may be related to mount.',C('mound.s1','土堆土丘','The archaeologists uncovered a low mound of earth beside the river and found pottery fragments near its base.','考古学家在河边发现一座低矮土丘，并在底部附近找到陶器碎片。','The archaeologists uncovered a low mound of earth beside the river / and found pottery fragments / near its base.','mound 指隆起的土堆、石堆或小土丘。','河边的隆起地形埋有古代遗物。'),M('The archaeologists described a deep trench cut into the ground as a raised mound of earth.','The archaeologists described the raised heap beside the river as a mound.','向下挖出的沟槽不是隆起的土堆。','meaning'),[q('What did archaeologists find near the mound?','pottery fragments','moth larvae','a mortgage contract','陶片出现在土丘底部附近。'),q('A mound is best described as?','a raised heap of earth or stones','a deep hole below ground','a road for fast vehicles','mound 指隆起的土堆或石堆。',1),q('Which site contains a mound?','a low raised earth bank beside a river','a trench cut several metres downward','a flat sheet of glass','隆起的河边土丘符合 mound。',1,'context'),q('What remains uncertain about mound?','its deeper etymological origin','whether earth can form heaps','whether archaeologists study pottery','更深层词源不确定，可能与 mount 有关。',1,'word-formation')]);
P('mount','Mount came from Old French munter and Latin mons, “mountain”; its verb senses include climbing, increasing, beginning an event, or fixing something in place, and Mount appears in names.',[C('mount.s1','登上攀爬','At dawn, the climbers mounted the ridge before the afternoon storm reached the exposed peak.','黎明时，登山者爬上山脊，赶在午后风暴抵达无遮蔽的山峰前行动。','At dawn / the climbers mounted the ridge / before the afternoon storm / reached the exposed peak.','mount 作动词可表示登上高处或骑上交通工具。','登山者向上攀上山脊。'),C('mount.s2','逐渐增加','As the repair deadline approached, pressure mounted on the engineers to reopen the bridge safely.','维修期限临近时，工程师们承受的压力逐渐增大，必须安全重开桥梁。','As the repair deadline approached / pressure mounted on the engineers / to reopen the bridge safely.','mount 可表示数量、力量或压力逐渐增加。','期限逼近使压力一步步加大。'),C('mount.s3','发起组织','The museum will mount an exhibition of coastal maps to mark the harbour’s centenary.','博物馆将举办一场海岸地图展览，纪念港口建成一百周年。','The museum will mount an exhibition of coastal maps / to mark the harbour’s centenary.','mount an exhibition 表示组织并推出一场展览。','博物馆筹备并举办纪念展。'),C('mount.s4','安装固定','The technician mounted the camera on a bracket above the laboratory door.','技术员把摄像机安装在实验室门上方的支架上。','The technician mounted the camera / on a bracket / above the laboratory door.','mount 作动词也可表示把物品牢固装到支架或底座上。','摄像机固定在支架上。'),C('mount.s5','山峰名称','The walkers reached Mount Snowdon before sunrise and watched the cloud layer lift from the summit.','徒步者在日出前抵达斯诺登山，并看着云层从山顶散开。','The walkers reached Mount Snowdon / before sunrise / and watched the cloud layer lift from the summit.','Mount 可置于专名之前表示山峰。','Mount Snowdon 是山名中的 Mount 用法。')],M('The technician mounted the camera by leaving it loose on the floor, where it could not stay fixed.','The technician mounted the camera securely on the wall bracket.','mount 表示安装固定，随意放在地上并非安装。','meaning'),[q('What did the climbers mount?','the ridge','the camera bracket','the exhibition catalogue','他们爬上山脊。',1),q('What happened to pressure as the deadline approached?','it increased gradually','it disappeared at once','it became a mountain name','pressure mounted 表示压力逐渐增大。',2),q('What did the museum mount?','an exhibition of coastal maps','a camera above the door','a ridge before a storm','mount an exhibition 表示举办展览。',3),q('In Mount Snowdon, Mount is?','part of a mountain’s proper name','a verb meaning to arrange a show','a measure of pressure','专名中的 Mount 表示山峰。',5,'distinction')]);
P('mountain','Mountain came through Old French montaigne from Latin montanea, “mountainous region”; it can mean a high landform or a very large amount.',[C('mountain.s1','高大地形','The narrow path climbed the mountain through pine forest before reaching a rocky summit above the clouds.','狭窄小径穿过松林登上高山，最后抵达云层之上的岩石山顶。','The narrow path climbed the mountain / through pine forest / before reaching a rocky summit above the clouds.','mountain 指比丘陵更高、更陡的大块陆地。','森林、陡坡与山顶构成典型高山地形。'),C('mountain.s2','大量事物','The audit left a mountain of receipts on the accountant’s desk, each needing to be checked against the travel claims.','审计后会计桌上堆着大量收据，每张都要与差旅报销单核对。','The audit left a mountain of receipts / on the accountant’s desk / each needing to be checked against the travel claims.','a mountain of 可比喻数量非常大的事物。','成堆待核对的收据数量庞大。')],M('The accountant described one receipt on an empty desk as a mountain of paperwork.','The accountant described the towering stack of receipts as a mountain of paperwork.','单张收据不是大量堆积的文件。','meaning'),[q('Where did the path lead?','to a rocky summit above the clouds','to a harbour wall','to a monthly meeting','登山小径最后抵达云层之上的山顶。',1),q('What filled the accountant’s desk?','a very large pile of receipts','one empty folder','a single mountain bike','审计留下大量待核对收据。',2),q('Which use is figurative?','a mountain of receipts','a steep mountain with a summit','a mountain above the clouds','收据的“山”是数量很多的比喻。',1,'distinction'),q('A mountain is generally higher and steeper than a?','hill','mote','mound of receipts','mountain 指比 hill 更高、更陡的地形。',1,'distinction')]);
P('mountainous','Mountainous is mountain plus -ous; it describes land with many mountains or, figuratively, a task that is very large and difficult.',[C('mountainous.s1','多山地区','The bus crossed a mountainous region on winding roads that climbed through several high passes.','公交车沿蜿蜒道路穿过多山地区，翻越了几个高山隘口。','The bus crossed a mountainous region / on winding roads / that climbed through several high passes.','mountainous 描述有许多山或被山地覆盖的地区。','多条山口和盘山路表明地形多山。'),C('mountainous.s2','巨大艰难','The volunteers faced a mountainous backlog of forms after the storm displaced hundreds of families.','风暴使数百户家庭流离失所后，志愿者们面对堆积如山的表格积压。','The volunteers faced a mountainous backlog of forms / after the storm displaced hundreds of families.','mountainous 可比喻规模巨大、难以应付的数量或任务。','表格积压很多，工作量艰巨。')],M('The bus crossed a mountainous region of perfectly level plains with no hills or high passes.','The bus crossed a mountainous region of winding roads and high passes.','没有山丘或山口的平原不是多山地带。','meaning'),[q('What kind of roads did the bus follow?','winding roads through high passes','straight roads across a flat desert','a motorway through a city only','车辆穿过蜿蜒山路和高山隘口。'),q('What was mountainous after the storm?','the backlog of forms','the volunteers’ single pencil','the flat bus station','大量表格积压被比作山一样巨大。',2),q('Which use is figurative?','a mountainous backlog of paperwork','a mountainous region with high passes','a mountainous road over a ridge','堆积量大而难处理是比喻义。',1,'distinction'),q('Mountainous is formed from mountain plus?','-ous','-ly','-less','mountainous 由 mountain 加 -ous 构成形容词。',1,'word-formation')]);
P('mountainside','Mountainside combines mountain and side and means the sloping flank of a mountain between its summit and foot.',C('mountainside.s1','山坡侧面','A narrow stream ran down the eastern mountainside, cutting through scrub before reaching the valley floor.','一条窄溪沿东侧山坡流下，穿过灌木后到达谷底。','A narrow stream ran down the eastern mountainside / cutting through scrub / before reaching the valley floor.','mountainside 指山顶与山脚之间的山体侧坡。','溪水从山坡向谷底流淌。'),M('The hikers reached the mountainside at the valley floor and said they were standing on the summit.','The hikers climbed the mountainside from the valley toward the summit.','山坡侧面不等同于山顶；谷底也不是 summit。','distinction'),[q('Where did the stream flow?','down the eastern slope toward the valley','up from the valley into the sky','across a mosque roof','溪水沿山坡流向谷底。'),q('A mountainside is the?','flank or slope of a mountain','highest point only','flat land far from any mountain','mountainside 指山的侧坡。',1,'meaning'),q('Which location is a mountainside?','the slope between a mountain’s foot and summit','the valley floor beyond the mountain','the exact summit peak only','山脚与山顶之间的坡面是 mountainside。',1,'context'),q('The compound joins mountain with?','side','motive','moss','mountainside 由 mountain 与 side 组成。',1,'word-formation')]);
P('mourn','Mourn continues Old English murnan, “grieve”; it means to feel and show sadness after a death or to regret a lost thing or opportunity.',[C('mourn.s1','哀悼逝者','The village gathered at the harbour to mourn the rescue workers who had died during the winter storm.','村民聚集在港口，哀悼在冬季风暴中遇难的救援人员。','The village gathered at the harbour / to mourn the rescue workers / who had died during the winter storm.','mourn 常指因某人去世而感到并表达悲伤。','村民通过聚集悼念遇难者。'),C('mourn.s2','惋惜失去','After the old footbridge closed, residents mourned the loss of the short route to the market.','旧人行桥关闭后，居民惋惜失去了去市场的近路。','After the old footbridge closed / residents mourned the loss / of the short route to the market.','mourn 也可指为失去某种事物或机会而深感惋惜。','居民怀念并惋惜不再能走近路。')],M('The villagers mourned the rescue workers, celebrating their deaths as a happy occasion.','The villagers mourned the rescue workers’ deaths with sadness and a memorial gathering.','庆祝死亡与哀悼的悲伤含义相反。','meaning'),[q('Whom did the village mourn?','rescue workers who died in the storm','market sellers at the station','a motor race winner only','村民悼念在风暴中遇难的救援人员。'),q('What did residents lose when the footbridge closed?','a short route to the market','a monthly periodical','a mountain summit','居民惋惜失去通往市场的近路。',2),q('Which use refers to a death?','They mourned the rescue workers.','They mourned the loss of a shortcut.','They mounted an exhibition.','第一例因人员去世而哀悼。',1,'distinction'),q('Which use refers to something other than a death?','mourn the loss of a route','mourn a worker who died','mourn at a funeral','第二例 mourn 的对象是失去的近路。',2,'distinction')]);
P('mournful','Mournful combines mourn and -ful and describes sadness or something that creates a sad impression.',C('mournful.s1','悲伤语调','A mournful cello melody filled the hall as the choir sang slowly beneath the memorial’s stone arch.','合唱团在纪念碑的石拱下缓缓歌唱，悲伤的大提琴旋律充满大厅。','A mournful cello melody filled the hall / as the choir sang slowly / beneath the memorial’s stone arch.','mournful 可形容带有悲痛或凄凉感觉的人、声音或作品。','缓慢合唱和大提琴旋律营造哀伤氛围。'),M('The cello played a mournful melody that made listeners feel cheerful and eager to dance.','The cello played a mournful melody that made listeners feel sad and reflective.','使人欢快起舞的效果与 mournful 的悲伤感相反。','meaning'),[q('What filled the hall?','a sad-sounding cello melody','a motor race announcement','a monthly financial report','大厅里回荡着悲伤的大提琴旋律。'),q('How did the choir sing?','slowly beneath the memorial arch','loudly on a motorway','silently in a motel','合唱团在纪念拱门下缓慢歌唱。',1),q('Which sound is mournful?','a slow, sorrowful cello line','a bright celebratory trumpet fanfare','a neutral clock tick','悲伤的大提琴旋律具有 mournful 的感觉。',1,'context'),q('Mournful is formed by adding -ful to?','mourn','motel','mound','mournful 由 mourn 加 -ful 构成形容词。',1,'word-formation')]);
})();
